INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u5-C1','math',1,1,'u5',2,'10 알아보기 — 9보다 1만큼 더 큰 수 10을 세고 쓰고 「열·십」으로 읽으며, 10을 두 수로 가르고 모으기',ARRAY['2수01-01']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u5-C2','math',1,1,'u5',4,'십몇 알아보기 — 10개씩 묶음 1개와 낱개 몇 개로 11~19를 나타내고, 「열둘·십이」처럼 두 가지로 읽기',ARRAY['2수01-01']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u5-C3','math',1,1,'u5',5,'십몇 모으기와 가르기 — 한 자리 수 두 개를 모아 십몇을 만들고(큰 수부터 이어 세기), 십몇을 한 자리 수 두 개로 여러 가지로 가르기',ARRAY['2수01-04']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u5-C4','math',1,1,'u5',6,'몇십 알아보기 — 10개씩 묶음 2~5개를 20·30·40·50으로 쓰고 「스물·이십」처럼 읽으며, 묶음 수로 몇십을 견주기',ARRAY['2수01-01']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u5-C5','math',1,1,'u5',7,'50까지의 수 세기 — 10개씩 묶음과 낱개로 세어 몇십몇을 쓰고 두 가지로 읽기, 낱개가 10개면 묶음 하나로 바꾸기',ARRAY['2수01-01']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u5-C6','math',1,1,'u5',8,'50까지 수의 순서 — 1만큼 더 큰/작은 수, 사이의 수, 낱개 9 다음 몇십으로 넘어가기, 수 배열표의 옆 칸(1씩)과 위아래 칸(10씩)',ARRAY['2수01-03']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u5-C7','math',1,1,'u5',9,'수의 크기 비교 — 10개씩 묶음의 수를 먼저 견주고, 같으면 낱개를 견주며, 셋 이상에서 가장 큰/작은 수 찾기',ARRAY['2수01-03']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X01','math',1,'u5',ARRAY['M1-1-u5-C1']::text[],'9 다음 수를 모르거나 10을 「1」과 「0」 두 수로 따로 본다(일영·01·1)','십 배열판 열 칸을 모두 채운 뒤 「한 판 = 10」을 손으로 짚으며 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X02','math',1,'u5',ARRAY['M1-1-u5-C1','M1-1-u5-C2','M1-1-u5-C4','M1-1-u5-C5']::text[],'두 가지 읽기를 섞는다 — 12를 「열이」, 23을 「스물삼」, 30을 「셋십」','「이십삼」 줄과 「스물셋」 줄을 따로 적어 두고, 한 수는 한 줄에서만 읽게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X03','math',1,'u5',ARRAY['M1-1-u5-C1','M1-1-u5-C3']::text[],'가르기 짝을 잘못 찾는다 — 한 수를 그대로 쓰거나 1 차이로(10을 4와 5로)','가른 두 수를 다시 모아 처음 수가 되는지 확인하는 습관 들이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X04','math',1,'u5',ARRAY['M1-1-u5-C2','M1-1-u5-C5']::text[],'묶음과 낱개의 자리를 바꿔 쓴다 — 묶음 1·낱개 4를 41로, 23을 32로','「묶음이 앞, 낱개가 뒤」 — 수 카드 두 칸에 묶음 막대와 낱개 구슬을 직접 올려 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X05','math',1,'u5',ARRAY['M1-1-u5-C1','M1-1-u5-C2','M1-1-u5-C4','M1-1-u5-C5']::text[],'묶음 하나를 1로 센다 — 묶음 3개를 3, 묶음 1·낱개 4를 5로','묶음 하나를 풀어 10개를 하나씩 세어 본 뒤 다시 묶기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X06','math',1,'u5',ARRAY['M1-1-u5-C2','M1-1-u5-C5']::text[],'낱개가 10개 이상인데 묶음으로 바꾸지 않는다 — 묶음 2·낱개 12를 212나 22로','낱개를 10개씩 끈으로 묶어 묶음 칸으로 옮기는 놀이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X07','math',1,'u5',ARRAY['M1-1-u5-C4','M1-1-u5-C5']::text[],'0을 빠뜨리거나 덧붙인다 — 30을 3으로, 이십삼을 203으로','낱개 칸이 비면 0을 써서 자리를 지킨다는 것을 수 카드 두 칸으로 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X08','math',1,'u5',ARRAY['M1-1-u5-C3']::text[],'이어 세기에서 시작 수를 한 번 더 세거나 빠뜨려 1 차이가 난다(9와 6을 모아 14나 16)','시작 수는 머리에 두고 「열, 열하나…」처럼 다음 수부터 손가락을 펴게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X09','math',1,'u5',ARRAY['M1-1-u5-C1','M1-1-u5-C3']::text[],'가르기를 모으기로 한다 — 두 수를 더하거나 전체 수를 그대로 답으로 쓴다','「가르기 = 하나를 둘로 나누기」 — 구슬을 두 손에 나누어 쥐는 동작으로 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X10','math',1,'u5',ARRAY['M1-1-u5-C6']::text[],'1만큼 더 큰 수와 더 작은 수를 거꾸로 찾는다','수 배열표에서 오른쪽은 커지고 왼쪽은 작아진다는 것을 손가락으로 따라가기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X11','math',1,'u5',ARRAY['M1-1-u5-C6']::text[],'낱개 9에서 몇십으로 넘어가지 못한다 — 29 다음을 20이나 210으로, 40 바로 앞을 49로','낱개 9개에 하나를 더하면 10개 — 묶음 하나가 새로 생기는 것을 구슬로 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X12','math',1,'u5',ARRAY['M1-1-u5-C6']::text[],'1씩과 10씩을 섞는다 — 1만큼 큰 수를 10만큼 큰 수로, 배열표 위아래 칸을 1 차이로','배열표에서 옆으로 한 칸(1), 아래로 한 칸(10)을 색을 달리해 칠하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X13','math',1,'u5',ARRAY['M1-1-u5-C6']::text[],'사이의 수에 양 끝 수를 넣거나 하나를 빠뜨린다','양 끝 수에 동그라미를 치고 그 안쪽 수만 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X14','math',1,'u5',ARRAY['M1-1-u5-C7']::text[],'낱개부터 견준다 — 낱개가 큰 29가 41보다 크다고 한다','두 수를 묶음 막대로 놓아 묶음 수부터 견주게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X15','math',1,'u5',ARRAY['M1-1-u5-C7']::text[],'묶음이 같으면 크기를 못 정하거나 「같다」고 한다','묶음이 같으면 낱개 구슬만 남겨 하나씩 짝지어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u5-X16','math',1,'u5',ARRAY['M1-1-u5-C6','M1-1-u5-C7']::text[],'묻는 말(더 큰/더 작은, 가장 큰/가장 작은)을 거꾸로 읽는다','물음의 「큰·작은」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_basic#1','math',1,1,'u5','L02','g1_1_math_u5_L02_basic','lesson_basic','M1-1-u5-C1',1,'mc','auto','십 배열판에 9개가 있어요. 1개를 더 놓으면 모두 몇 개인가요?',ARRAY['M1-1-u5-X01','M1-1-u5-X08']::text[],true,'{"seq":1,"concept":"M1-1-u5-C1","difficulty":1,"kind":"mc","stem":"십 배열판에 9개가 있어요. 1개를 더 놓으면 모두 몇 개인가요?","options":[{"t":"10","correct":true},{"t":"9","mis":"M1-1-u5-X01"},{"t":"11","mis":"M1-1-u5-X08"}],"explanation":["9개가 놓인 판에 1개를 더 놓았어요.","열 칸이 모두 찼어요 — 10개예요.","9보다 1만큼 더 큰 수가 10이에요."],"asset":{"type":"ten_frame","filled":9,"add":1},"variant_rule":{"alt":[{"stem":"9보다 1만큼 더 큰 수는 무엇인가요?","options":[{"t":"10","correct":true},{"t":"8","mis":"M1-1-u5-X10"},{"t":"91","mis":"M1-1-u5-X01"}],"explanation":["9 바로 다음 수를 찾아요.","9 다음 수는 10이에요.","10은 1과 0 두 숫자로 쓰지만 하나의 수예요."],"asset":null},{"stem":"달걀 판 열 칸 가운데 9칸에 달걀이 있어요. 빈칸에 1개를 채우면 달걀은 모두 몇 개인가요?","options":[{"t":"10","correct":true},{"t":"9","mis":"M1-1-u5-X01"},{"t":"1","mis":"M1-1-u5-X01"}],"explanation":["9칸이 차 있었어요.","1개를 채우면 열 칸이 다 차서 10개예요.","열 칸이 꽉 차면 10이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_basic#2','math',1,1,'u5','L02','g1_1_math_u5_L02_basic','lesson_basic','M1-1-u5-C1',1,'sa','auto','십 배열판에 7개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?','{}'::text[],true,'{"seq":2,"concept":"M1-1-u5-C1","difficulty":1,"kind":"sa","stem":"십 배열판에 7개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?","answer":["3"],"explanation":["빈칸을 세어 보세요 — 3칸이 비어 있어요.","7과 3을 모으면 10이에요.","십 배열판은 열 칸이 다 차야 10이에요."],"asset":{"type":"ten_frame","filled":7,"add":0},"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_basic#3','math',1,1,'u5','L02','g1_1_math_u5_L02_basic','lesson_basic','M1-1-u5-C1',1,'mc','auto','10을 바르게 읽은 것은 어느 것인가요?',ARRAY['M1-1-u5-X01','M1-1-u5-X10']::text[],true,'{"seq":3,"concept":"M1-1-u5-C1","difficulty":1,"kind":"mc","stem":"10을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"열 또는 십","correct":true},{"t":"일영","mis":"M1-1-u5-X01"},{"t":"열하나","mis":"M1-1-u5-X10"}],"explanation":["10은 두 가지로 읽어요.","「열」 또는 「십」이라고 읽어요.","1과 0을 따로 읽지 않아요."],"variant_rule":{"alt":[{"stem":"「열」을 수로 쓰면 무엇인가요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M1-1-u5-X01"},{"t":"01","mis":"M1-1-u5-X01"}],"explanation":["「열」은 9보다 1만큼 더 큰 수예요.","수로 쓰면 10이에요.","1을 앞에, 0을 뒤에 써요."]},{"stem":"「십」을 수로 쓰면 무엇인가요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M1-1-u5-X01"},{"t":"100","mis":"M1-1-u5-X07"}],"explanation":["「십」은 「열」과 같은 수예요.","수로 쓰면 10이에요.","1과 0, 두 숫자로 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_basic#4','math',1,1,'u5','L02','g1_1_math_u5_L02_basic','lesson_basic','M1-1-u5-C1',1,'mc','auto','10을 두 수로 가르기 했어요. 6 옆의 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M1-1-u5-X03','M1-1-u5-X09']::text[],true,'{"seq":4,"concept":"M1-1-u5-C1","difficulty":1,"kind":"mc","stem":"10을 두 수로 가르기 했어요. 6 옆의 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"6","mis":"M1-1-u5-X03"},{"t":"10","mis":"M1-1-u5-X09"}],"explanation":["10을 둘로 갈랐어요.","6을 뺀 나머지는 4예요.","가른 두 수를 모으면 다시 10이 돼요."],"asset":{"type":"number_bond","whole":10,"parts":[6,null]},"variant_rule":{"bond":{"whole":[10,10],"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_basic#5','math',1,1,'u5','L02','g1_1_math_u5_L02_basic','lesson_basic','M1-1-u5-C1',2,'mc','auto','3과 7을 모으면 얼마인가요?',ARRAY['M1-1-u5-X08']::text[],true,'{"seq":5,"concept":"M1-1-u5-C1","difficulty":2,"kind":"mc","stem":"3과 7을 모으면 얼마인가요?","options":[{"t":"10","correct":true},{"t":"9","mis":"M1-1-u5-X08"},{"t":"11","mis":"M1-1-u5-X08"}],"explanation":["3과 7을 모아요.","7부터 이어 세면 8, 9, 10 — 10이에요.","모으기는 두 수를 합치는 거예요."],"asset":{"type":"number_bond","whole":null,"parts":[3,7]},"variant_rule":{"bond":{"whole":[10,10],"ask":"whole"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_basic#6','math',1,1,'u5','L02','g1_1_math_u5_L02_basic','lesson_basic','M1-1-u5-C1',2,'ox','auto','달걀이 한 줄에 5개씩 두 줄 있어요. 달걀은 모두 10개예요.',ARRAY['M1-1-u5-X05']::text[],true,'{"seq":6,"concept":"M1-1-u5-C1","difficulty":2,"kind":"ox","stem":"달걀이 한 줄에 5개씩 두 줄 있어요. 달걀은 모두 10개예요.","answer":"O","reason_options":[{"t":"5와 5를 모으면 10이니까","correct":true},{"t":"두 줄이니까 2개라고 세어야 하니까","mis":"M1-1-u5-X05"}],"mis":"M1-1-u5-X05","explanation":["한 줄에 5개, 두 줄이에요.","5와 5를 모으면 10이에요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"산딸기가 한 줄에 4개씩 두 줄 있어요. 산딸기는 모두 10개예요.","answer":"X","reason_options":[{"t":"4와 4를 모으면 8이니까","correct":true},{"t":"두 줄이면 언제나 10이니까","mis":"M1-1-u5-X03"}],"explanation":["한 줄에 4개, 두 줄이에요.","4와 4를 모으면 8이에요.","10이 되려면 한 줄에 5개씩 있어야 해요."]},{"stem":"빨대가 한 묶음에 10개씩 1묶음 있어요. 빨대는 모두 1개예요.","answer":"X","reason_options":[{"t":"한 묶음 안에 빨대가 10개 있으니까","correct":true},{"t":"묶음이 하나니까 1개라서","mis":"M1-1-u5-X05"}],"explanation":["묶음은 하나지만 그 안에 빨대가 10개 있어요.","빨대는 모두 10개예요.","묶음 하나는 10개라는 뜻이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_basic#7','math',1,1,'u5','L02','g1_1_math_u5_L02_basic','lesson_basic','M1-1-u5-C1',2,'match','auto','모아서 10이 되는 두 수끼리 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u5-C1","difficulty":2,"kind":"match","stem":"모아서 10이 되는 두 수끼리 이어 보세요.","pairs":[{"l":"1","r":"9"},{"l":"3","r":"7"},{"l":"4","r":"6"}],"mis":"M1-1-u5-X03","explanation":["1과 9를 모으면 10이에요.","3과 7, 4와 6도 모으면 10이에요.","모은 수가 10이 되는지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모아서 10이 되는 두 수끼리 이어 보세요.","pairs":[{"l":"2","r":"8"},{"l":"5","r":"5"},{"l":"7","r":"3"}],"explanation":["2와 8을 모으면 10이에요.","5와 5, 7과 3도 모으면 10이에요.","모은 수가 10이 되는지 확인해요."]},{"stem":"10을 가르기 했어요. 짝이 되는 수끼리 이어 보세요.","pairs":[{"l":"9","r":"1"},{"l":"6","r":"4"},{"l":"8","r":"2"}],"explanation":["10은 9와 1로 가를 수 있어요.","6과 4, 8과 2로도 갈라요.","가른 두 수를 모으면 다시 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_basic#8','math',1,1,'u5','L02','g1_1_math_u5_L02_basic','lesson_basic','M1-1-u5-C1',2,'blank','auto','9보다 1만큼 더 큰 수는 (        )이고, 「열」 또는 「십」이라고 읽어요.',ARRAY['M1-1-u5-X10','M1-1-u5-X01']::text[],true,'{"seq":8,"concept":"M1-1-u5-C1","difficulty":2,"kind":"blank","stem":"9보다 1만큼 더 큰 수는 (        )이고, 「열」 또는 「십」이라고 읽어요.","options":[{"t":"10","correct":true},{"t":"8","mis":"M1-1-u5-X10"},{"t":"91","mis":"M1-1-u5-X01"}],"explanation":["9 바로 다음 수를 찾아요.","9보다 1만큼 더 큰 수는 10이에요.","10은 「열」 또는 「십」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"10은 9보다 (        )만큼 더 큰 수예요.","options":[{"t":"1","correct":true},{"t":"9","mis":"M1-1-u5-X01"},{"t":"10","mis":"M1-1-u5-X09"}],"explanation":["9 바로 다음 수가 10이에요.","10은 9보다 1만큼 더 커요.","바로 다음 수는 1만큼 더 큰 수예요."]},{"stem":"10보다 1만큼 더 작은 수는 (        )예요.","options":[{"t":"9","correct":true},{"t":"11","mis":"M1-1-u5-X10"},{"t":"1","mis":"M1-1-u5-X01"}],"explanation":["10 바로 앞의 수를 찾아요.","10보다 1만큼 더 작은 수는 9예요.","바로 앞의 수는 1만큼 더 작은 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_basic#9','math',1,1,'u5','L02','g1_1_math_u5_L02_basic','lesson_basic','M1-1-u5-C1',2,'error','auto','친구들이 10에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u5-X01','M1-1-u5-X02']::text[],true,'{"seq":9,"concept":"M1-1-u5-C1","difficulty":2,"kind":"error","stem":"친구들이 10에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 10은 1과 0으로 쓰니까 1보다 조금 큰 수야.","correct":true,"mis_target":"M1-1-u5-X01"},{"t":"하루: 10은 9보다 1만큼 더 큰 수야.","mis":"M1-1-u5-X01"},{"t":"도이: 10은 열이라고도 읽고 십이라고도 읽어.","mis":"M1-1-u5-X02"}],"explanation":["10은 1과 0, 두 숫자로 써요.","하지만 1보다 9만큼이나 더 큰 수예요.","서아가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 10에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유나: 10은 「일영」이라고 읽어.","correct":true,"mis_target":"M1-1-u5-X01"},{"t":"지우: 10은 「열」이라고 읽어.","mis":"M1-1-u5-X02"},{"t":"하루: 10은 「십」이라고도 읽어.","mis":"M1-1-u5-X02"}],"explanation":["10은 「열」 또는 「십」이라고 읽어요.","1과 0을 따로 읽지 않아요.","유나가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_basic#10','math',1,1,'u5','L02','g1_1_math_u5_L02_basic','lesson_basic','M1-1-u5-C1',3,'sa','auto','10을 두 수로 가르는 방법은 모두 몇 가지인가요? (0은 쓰지 않고, 1과 9와 9와 1은 다른 방법으로 세어요.)','{}'::text[],false,'{"seq":10,"concept":"M1-1-u5-C1","difficulty":3,"kind":"sa","stem":"10을 두 수로 가르는 방법은 모두 몇 가지인가요? (0은 쓰지 않고, 1과 9와 9와 1은 다른 방법으로 세어요.)","answer":["9"],"explanation":["1과 9, 2와 8, 3과 7, 4와 6, 5와 5,","6과 4, 7과 3, 8과 2, 9와 1 — 모두 9가지예요.","앞의 수가 1씩 커지면 뒤의 수는 1씩 작아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_challenge#1','math',1,1,'u5','L02','g1_1_math_u5_L02_challenge','lesson_challenge','M1-1-u5-C1',2,'mc','auto','십 배열판에 6개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?',ARRAY['M1-1-u5-X03','M1-1-u5-X09']::text[],true,'{"seq":1,"concept":"M1-1-u5-C1","difficulty":2,"kind":"mc","stem":"십 배열판에 6개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?","options":[{"t":"4","correct":true},{"t":"6","mis":"M1-1-u5-X03"},{"t":"10","mis":"M1-1-u5-X09"}],"explanation":["빈칸이 4칸이에요.","6과 4를 모으면 10이에요.","빈칸 수가 더 놓을 수예요."],"asset":{"type":"ten_frame","filled":6,"add":0},"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_challenge#2','math',1,1,'u5','L02','g1_1_math_u5_L02_challenge','lesson_challenge','M1-1-u5-C1',2,'mc','auto','사탕 10개를 두 접시에 나누었더니 한 접시에 3개가 있어요. 다른 접시에는 몇 개가 있나요?',ARRAY['M1-1-u5-X03','M1-1-u5-X09']::text[],true,'{"seq":2,"concept":"M1-1-u5-C1","difficulty":2,"kind":"mc","stem":"사탕 10개를 두 접시에 나누었더니 한 접시에 3개가 있어요. 다른 접시에는 몇 개가 있나요?","options":[{"t":"7","correct":true},{"t":"3","mis":"M1-1-u5-X03"},{"t":"13","mis":"M1-1-u5-X09"}],"explanation":["10을 3과 몇으로 가르는지 찾아요.","10은 3과 7로 갈라요.","그래서 다른 접시에는 7개가 있어요."],"variant_rule":{"alt":[{"stem":"구슬 10개를 두 주머니에 나누었더니 한 주머니에 8개가 있어요. 다른 주머니에는 몇 개가 있나요?","options":[{"t":"2","correct":true},{"t":"8","mis":"M1-1-u5-X03"},{"t":"18","mis":"M1-1-u5-X09"}],"explanation":["10을 8과 몇으로 가르는지 찾아요.","10은 8과 2로 갈라요.","그래서 다른 주머니에는 2개가 있어요."]},{"stem":"연필 10자루를 두 필통에 나누었더니 한 필통에 5자루가 있어요. 다른 필통에는 몇 자루가 있나요?","options":[{"t":"5","correct":true},{"t":"4","mis":"M1-1-u5-X03"},{"t":"15","mis":"M1-1-u5-X09"}],"explanation":["10을 5와 몇으로 가르는지 찾아요.","10은 5와 5로 갈라요.","그래서 다른 필통에도 5자루가 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_challenge#3','math',1,1,'u5','L02','g1_1_math_u5_L02_challenge','lesson_challenge','M1-1-u5-C1',3,'mc','auto','10을 두 수로 가르기 했어요. 두 수의 차이가 2인 것은 어느 것인가요?',ARRAY['M1-1-u5-X03']::text[],true,'{"seq":3,"concept":"M1-1-u5-C1","difficulty":3,"kind":"mc","stem":"10을 두 수로 가르기 했어요. 두 수의 차이가 2인 것은 어느 것인가요?","options":[{"t":"6과 4","correct":true},{"t":"5와 5","mis":"M1-1-u5-X03"},{"t":"8과 2","mis":"M1-1-u5-X03"}],"explanation":["6과 4는 모으면 10이고 차이는 2예요.","5와 5는 차이가 없고, 8과 2는 차이가 6이에요.","두 조건을 모두 맞는지 확인해요."],"variant_rule":{"alt":[{"stem":"10을 두 수로 가르기 했어요. 두 수의 차이가 4인 것은 어느 것인가요?","options":[{"t":"7과 3","correct":true},{"t":"6과 4","mis":"M1-1-u5-X03"},{"t":"9와 1","mis":"M1-1-u5-X03"}],"explanation":["7과 3은 모으면 10이고 차이는 4예요.","6과 4는 차이가 2, 9와 1은 차이가 8이에요.","두 조건을 모두 맞는지 확인해요."]},{"stem":"10을 두 수로 가르기 했어요. 두 수가 같은 것은 어느 것인가요?","options":[{"t":"5와 5","correct":true},{"t":"4와 6","mis":"M1-1-u5-X03"},{"t":"2와 8","mis":"M1-1-u5-X03"}],"explanation":["5와 5는 모으면 10이고 두 수가 같아요.","4와 6, 2와 8은 두 수가 달라요.","10을 똑같이 가르면 5와 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_challenge#4','math',1,1,'u5','L02','g1_1_math_u5_L02_challenge','lesson_challenge','M1-1-u5-C1',3,'ox','auto','10을 9와 1, 8과 2, 7과 3 … 으로 가를 때, 앞의 수가 1씩 작아지면 뒤의 수는 1씩 커져요.',ARRAY['M1-1-u5-X03']::text[],true,'{"seq":4,"concept":"M1-1-u5-C1","difficulty":3,"kind":"ox","stem":"10을 9와 1, 8과 2, 7과 3 … 으로 가를 때, 앞의 수가 1씩 작아지면 뒤의 수는 1씩 커져요.","answer":"O","reason_options":[{"t":"두 수를 모으면 언제나 10이 되어야 하니까","correct":true},{"t":"두 수가 같이 작아져야 하니까","mis":"M1-1-u5-X03"}],"mis":"M1-1-u5-X03","explanation":["9와 1, 8과 2, 7과 3 — 앞의 수는 1씩 작아져요.","뒤의 수는 1, 2, 3으로 1씩 커져요.","모아서 10이 되려면 한쪽이 줄면 다른 쪽이 늘어요."],"variant_rule":{"alt":[{"stem":"10을 1과 9, 2와 8, 3과 7 … 으로 가를 때, 앞의 수가 1씩 커지면 뒤의 수도 1씩 커져요.","answer":"X","reason_options":[{"t":"모아서 10이 되려면 앞의 수가 커질 때 뒤의 수는 작아지니까","correct":true},{"t":"앞의 수를 따라 뒤의 수도 커져야 하니까","mis":"M1-1-u5-X03"}],"explanation":["1과 9, 2와 8, 3과 7 이에요.","앞의 수가 커지면 뒤의 수는 9, 8, 7로 작아져요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_challenge#5','math',1,1,'u5','L02','g1_1_math_u5_L02_challenge','lesson_challenge','M1-1-u5-C1',3,'sa','auto','구슬 10개를 두 주머니에 나누어 넣었어요. 한 주머니가 다른 주머니보다 4개 더 많아요. 많은 주머니에는 몇 개가 있나요?','{}'::text[],true,'{"seq":5,"concept":"M1-1-u5-C1","difficulty":3,"kind":"sa","stem":"구슬 10개를 두 주머니에 나누어 넣었어요. 한 주머니가 다른 주머니보다 4개 더 많아요. 많은 주머니에는 몇 개가 있나요?","answer":["7"],"explanation":["10을 두 수로 가르고 차이가 4인 것을 찾아요.","7과 3 — 차이가 4예요.","많은 주머니에는 7개가 있어요."],"variant_rule":{"alt":[{"stem":"구슬 10개를 두 주머니에 나누어 넣었어요. 한 주머니가 다른 주머니보다 6개 더 많아요. 많은 주머니에는 몇 개가 있나요?","answer":["8"],"explanation":["10을 두 수로 가르고 차이가 6인 것을 찾아요.","8과 2 — 차이가 6이에요.","많은 주머니에는 8개가 있어요."]},{"stem":"구슬 10개를 두 주머니에 나누어 넣었어요. 한 주머니가 다른 주머니보다 2개 더 많아요. 적은 주머니에는 몇 개가 있나요?","answer":["4"],"explanation":["10을 두 수로 가르고 차이가 2인 것을 찾아요.","6과 4 — 차이가 2예요.","적은 주머니에는 4개가 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_challenge#6','math',1,1,'u5','L02','g1_1_math_u5_L02_challenge','lesson_challenge','M1-1-u5-C1',3,'mc','auto','□ 안에 들어갈 수가 가장 큰 것은 어느 것인가요?',ARRAY['M1-1-u5-X16','M1-1-u5-X03']::text[],true,'{"seq":6,"concept":"M1-1-u5-C1","difficulty":3,"kind":"mc","stem":"□ 안에 들어갈 수가 가장 큰 것은 어느 것인가요?","options":[{"t":"2와 □를 모으면 10","correct":true},{"t":"5와 □를 모으면 10","mis":"M1-1-u5-X16"},{"t":"7과 □를 모으면 10","mis":"M1-1-u5-X03"}],"explanation":["2와 8, 5와 5, 7과 3을 모으면 10이에요.","□는 8, 5, 3이에요.","가장 큰 것은 「2와 □」의 8이에요."],"variant_rule":{"alt":[{"stem":"□ 안에 들어갈 수가 가장 작은 것은 어느 것인가요?","options":[{"t":"9와 □를 모으면 10","correct":true},{"t":"4와 □를 모으면 10","mis":"M1-1-u5-X16"},{"t":"6과 □를 모으면 10","mis":"M1-1-u5-X03"}],"explanation":["9와 1, 4와 6, 6과 4를 모으면 10이에요.","□는 1, 6, 4예요.","가장 작은 것은 「9와 □」의 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_challenge#7','math',1,1,'u5','L02','g1_1_math_u5_L02_challenge','lesson_challenge','M1-1-u5-C1',3,'error','auto','지우가 10을 여러 가지로 갈랐어요. 잘못 가른 것은 어느 것인가요?',ARRAY['M1-1-u5-X03']::text[],true,'{"seq":7,"concept":"M1-1-u5-C1","difficulty":3,"kind":"error","stem":"지우가 10을 여러 가지로 갈랐어요. 잘못 가른 것은 어느 것인가요?","options":[{"t":"6과 3","correct":true,"mis_target":"M1-1-u5-X03"},{"t":"4와 6","mis":"M1-1-u5-X03"},{"t":"1과 9","mis":"M1-1-u5-X03"}],"explanation":["6과 3을 모으면 9예요.","10이 되려면 6과 4여야 해요.","가른 두 수를 다시 모아 보면 실수를 찾을 수 있어요."],"variant_rule":{"alt":[{"stem":"하루가 10을 여러 가지로 갈랐어요. 잘못 가른 것은 어느 것인가요?","options":[{"t":"5와 4","correct":true,"mis_target":"M1-1-u5-X03"},{"t":"2와 8","mis":"M1-1-u5-X03"},{"t":"7과 3","mis":"M1-1-u5-X03"}],"explanation":["5와 4를 모으면 9예요.","10이 되려면 5와 5여야 해요.","가른 두 수를 다시 모아 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_challenge#8','math',1,1,'u5','L02','g1_1_math_u5_L02_challenge','lesson_challenge','M1-1-u5-C1',4,'mc','auto','지우는 구슬 4개, 하루는 구슬 3개를 가지고 있어요. 서아까지 세 친구의 구슬을 모두 모으면 10개예요. 서아는 구슬을 몇 개 가지고 있나요?',ARRAY['M1-1-u5-X03','M1-1-u5-X09']::text[],true,'{"seq":8,"concept":"M1-1-u5-C1","difficulty":4,"kind":"mc","stem":"지우는 구슬 4개, 하루는 구슬 3개를 가지고 있어요. 서아까지 세 친구의 구슬을 모두 모으면 10개예요. 서아는 구슬을 몇 개 가지고 있나요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M1-1-u5-X03"},{"t":"7","mis":"M1-1-u5-X09"}],"explanation":["지우와 하루의 구슬을 모으면 7개예요.","7과 3을 모으면 10이에요.","그래서 서아는 3개를 가지고 있어요."],"variant_rule":{"alt":[{"stem":"지우는 구슬 2개, 하루는 구슬 3개를 가지고 있어요. 서아까지 세 친구의 구슬을 모두 모으면 10개예요. 서아는 구슬을 몇 개 가지고 있나요?","options":[{"t":"5","correct":true},{"t":"8","mis":"M1-1-u5-X03"},{"t":"15","mis":"M1-1-u5-X09"}],"explanation":["지우와 하루의 구슬을 모으면 5개예요.","5와 5를 모으면 10이에요.","그래서 서아는 5개를 가지고 있어요."]},{"stem":"지우는 구슬 1개, 하루는 구슬 5개를 가지고 있어요. 서아까지 세 친구의 구슬을 모두 모으면 10개예요. 서아는 구슬을 몇 개 가지고 있나요?","options":[{"t":"4","correct":true},{"t":"9","mis":"M1-1-u5-X03"},{"t":"6","mis":"M1-1-u5-X09"}],"explanation":["지우와 하루의 구슬을 모으면 6개예요.","6과 4를 모으면 10이에요.","그래서 서아는 4개를 가지고 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_challenge#9','math',1,1,'u5','L02','g1_1_math_u5_L02_challenge','lesson_challenge','M1-1-u5-C1',4,'essay','teacher','10을 두 수로 가르는 방법을 세 가지 쓰고, 써 놓은 것들에서 어떤 규칙이 보이는지 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-1-u5-C1","difficulty":4,"kind":"essay","stem":"10을 두 수로 가르는 방법을 세 가지 쓰고, 써 놓은 것들에서 어떤 규칙이 보이는지 말해 보세요.","answer_guide":{"answer":"예: 9와 1, 8과 2, 7과 3. 앞의 수가 1씩 작아지면 뒤의 수는 1씩 커진다(두 수를 모으면 언제나 10).","scoring_points":["모아서 10이 되는 짝을 세 가지 바르게 썼는가","한쪽이 줄면 다른 쪽이 는다는 규칙을 말했는가","가른 두 수를 모으면 10이 된다는 것을 말했는가"]},"explanation":["9와 1, 8과 2, 7과 3처럼 쓸 수 있어요.","앞의 수가 1 작아지면 뒤의 수는 1 커져요.","두 수를 모으면 언제나 10이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L02_challenge#10','math',1,1,'u5','L02','g1_1_math_u5_L02_challenge','lesson_challenge','M1-1-u5-C1',4,'mc','auto','빈칸이 있는 십 배열판 두 개가 있어요. ㉮는 4칸, ㉯는 7칸이 차 있어요. 두 판을 모두 10이 되게 채우려면 모두 몇 개를 더 놓아야 하나요?',ARRAY['M1-1-u5-X09','M1-1-u5-X03']::text[],true,'{"seq":10,"concept":"M1-1-u5-C1","difficulty":4,"kind":"mc","stem":"빈칸이 있는 십 배열판 두 개가 있어요. ㉮는 4칸, ㉯는 7칸이 차 있어요. 두 판을 모두 10이 되게 채우려면 모두 몇 개를 더 놓아야 하나요?","options":[{"t":"9","correct":true},{"t":"11","mis":"M1-1-u5-X09"},{"t":"3","mis":"M1-1-u5-X03"}],"explanation":["㉮는 6개, ㉯는 3개를 더 놓아야 해요.","6과 3을 모으면 9예요.","그래서 모두 9개를 더 놓아요."],"variant_rule":{"alt":[{"stem":"빈칸이 있는 십 배열판 두 개가 있어요. ㉮는 8칸, ㉯는 5칸이 차 있어요. 두 판을 모두 10이 되게 채우려면 모두 몇 개를 더 놓아야 하나요?","options":[{"t":"7","correct":true},{"t":"13","mis":"M1-1-u5-X09"},{"t":"3","mis":"M1-1-u5-X03"}],"explanation":["㉮는 2개, ㉯는 5개를 더 놓아야 해요.","2와 5를 모으면 7이에요.","그래서 모두 7개를 더 놓아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_basic#1','math',1,1,'u5','L04','g1_1_math_u5_L04_basic','lesson_basic','M1-1-u5-C2',1,'mc','auto','10개씩 묶음 1개와 낱개 4개는 얼마인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X05']::text[],true,'{"seq":1,"concept":"M1-1-u5-C2","difficulty":1,"kind":"mc","stem":"10개씩 묶음 1개와 낱개 4개는 얼마인가요?","options":[{"t":"14","correct":true},{"t":"41","mis":"M1-1-u5-X04"},{"t":"5","mis":"M1-1-u5-X05"}],"explanation":["묶음 1개는 10이에요.","거기에 낱개 4개를 더하면 14예요.","묶음 수를 앞에, 낱개 수를 뒤에 써요."],"asset":{"type":"bundle_ones","tens":1,"ones":4},"variant_rule":{"bundle":{"tens":[1,1],"ones":[1,9],"ask":"number","cap":50}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_basic#2','math',1,1,'u5','L04','g1_1_math_u5_L04_basic','lesson_basic','M1-1-u5-C2',1,'sa','auto','그림을 보세요. 낱개는 몇 개인가요?','{}'::text[],true,'{"seq":2,"concept":"M1-1-u5-C2","difficulty":1,"kind":"sa","stem":"그림을 보세요. 낱개는 몇 개인가요?","answer":["7"],"explanation":["10개씩 묶음 1개와 낱개 7개예요.","낱개는 7개예요.","묶음은 10개짜리, 낱개는 하나씩이에요."],"asset":{"type":"bundle_ones","tens":1,"ones":7},"variant_rule":{"bundle":{"tens":[1,1],"ones":[1,9],"ask":"ones","cap":50}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_basic#3','math',1,1,'u5','L04','g1_1_math_u5_L04_basic','lesson_basic','M1-1-u5-C2',1,'mc','auto','12를 바르게 읽은 것은 어느 것인가요?',ARRAY['M1-1-u5-X02','M1-1-u5-X04']::text[],true,'{"seq":3,"concept":"M1-1-u5-C2","difficulty":1,"kind":"mc","stem":"12를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"열둘","correct":true},{"t":"열이","mis":"M1-1-u5-X02"},{"t":"스물하나","mis":"M1-1-u5-X04"}],"explanation":["12는 10개씩 묶음 1개와 낱개 2개예요.","「십이」 또는 「열둘」이라고 읽어요.","한 수를 읽을 때 두 가지 읽기를 섞지 않아요."],"variant_rule":{"read2":{"range":[11,19],"ask":"read","way":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_basic#4','math',1,1,'u5','L04','g1_1_math_u5_L04_basic','lesson_basic','M1-1-u5-C2',1,'mc','auto','17은 10개씩 묶음 1개와 낱개 몇 개인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X06']::text[],true,'{"seq":4,"concept":"M1-1-u5-C2","difficulty":1,"kind":"mc","stem":"17은 10개씩 묶음 1개와 낱개 몇 개인가요?","options":[{"t":"7","correct":true},{"t":"1","mis":"M1-1-u5-X04"},{"t":"17","mis":"M1-1-u5-X06"}],"explanation":["17의 앞자리 1은 묶음 1개예요.","뒷자리 7은 낱개 7개예요.","그래서 낱개는 7개예요."],"variant_rule":{"alt":[{"stem":"13은 10개씩 묶음 1개와 낱개 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"1","mis":"M1-1-u5-X04"},{"t":"13","mis":"M1-1-u5-X06"}],"explanation":["13의 앞자리 1은 묶음 1개예요.","뒷자리 3은 낱개 3개예요.","그래서 낱개는 3개예요."]},{"stem":"19는 10개씩 묶음 몇 개와 낱개 9개인가요?","options":[{"t":"1","correct":true},{"t":"9","mis":"M1-1-u5-X04"},{"t":"10","mis":"M1-1-u5-X05"}],"explanation":["19의 앞자리 1은 묶음이에요.","10개씩 묶음 1개와 낱개 9개예요.","묶음은 개수(1개)로 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_basic#5','math',1,1,'u5','L04','g1_1_math_u5_L04_basic','lesson_basic','M1-1-u5-C2',2,'mc','auto','「열다섯」을 수로 쓰면 무엇인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X07']::text[],true,'{"seq":5,"concept":"M1-1-u5-C2","difficulty":2,"kind":"mc","stem":"「열다섯」을 수로 쓰면 무엇인가요?","options":[{"t":"15","correct":true},{"t":"51","mis":"M1-1-u5-X04"},{"t":"105","mis":"M1-1-u5-X07"}],"explanation":["「열다섯」은 10개씩 묶음 1개와 낱개 5개예요.","수로 쓰면 15예요.","묶음 수를 앞에, 낱개 수를 뒤에 붙여 써요."],"variant_rule":{"read2":{"range":[11,19],"ask":"num","way":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_basic#6','math',1,1,'u5','L04','g1_1_math_u5_L04_basic','lesson_basic','M1-1-u5-C2',2,'ox','auto','10개씩 묶음 1개와 낱개 3개는 13이에요.',ARRAY['M1-1-u5-X05']::text[],true,'{"seq":6,"concept":"M1-1-u5-C2","difficulty":2,"kind":"ox","stem":"10개씩 묶음 1개와 낱개 3개는 13이에요.","answer":"O","reason_options":[{"t":"묶음 1개는 10이고 낱개 3개를 더하면 13이니까","correct":true},{"t":"묶음 1개와 낱개 3개를 모으면 4니까","mis":"M1-1-u5-X05"}],"mis":"M1-1-u5-X05","explanation":["묶음 1개는 10이에요.","10과 낱개 3개를 더하면 13이에요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"10개씩 묶음 1개와 낱개 8개는 81이에요.","answer":"X","reason_options":[{"t":"묶음 수를 앞에, 낱개 수를 뒤에 써서 18이니까","correct":true},{"t":"먼저 말한 수를 뒤에 써야 하니까","mis":"M1-1-u5-X04"}],"explanation":["묶음 1개와 낱개 8개예요.","묶음 수 1을 앞에, 낱개 수 8을 뒤에 써서 18이에요.","81은 자리를 바꿔 쓴 거예요."]},{"stem":"낱개 16개를 10개씩 묶으면 묶음 1개와 낱개 6개가 돼요.","answer":"O","reason_options":[{"t":"10개를 한 묶음으로 묶고 6개가 남으니까","correct":true},{"t":"낱개는 묶지 않고 16개 그대로 두어야 하니까","mis":"M1-1-u5-X06"}],"explanation":["16개 가운데 10개를 묶어요.","묶음 1개와 낱개 6개가 남아요.","낱개가 10개 넘으면 묶어서 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_basic#7','math',1,1,'u5','L04','g1_1_math_u5_L04_basic','lesson_basic','M1-1-u5-C2',2,'match','auto','수와 읽는 말을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u5-C2","difficulty":2,"kind":"match","stem":"수와 읽는 말을 알맞게 이어 보세요.","pairs":[{"l":"11","r":"열하나"},{"l":"14","r":"십사"},{"l":"19","r":"열아홉"}],"mis":"M1-1-u5-X02","explanation":["11은 열하나 또는 십일이에요.","14는 십사 또는 열넷, 19는 열아홉 또는 십구예요.","한 수를 읽을 때 두 가지 읽기를 섞지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 수와 읽는 말을 알맞게 이어 보세요.","pairs":[{"l":"13","r":"열셋"},{"l":"16","r":"십육"},{"l":"18","r":"열여덟"}],"explanation":["13은 열셋 또는 십삼이에요.","16은 십육 또는 열여섯, 18은 열여덟 또는 십팔이에요.","한 수를 읽을 때 두 가지 읽기를 섞지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_basic#8','math',1,1,'u5','L04','g1_1_math_u5_L04_basic','lesson_basic','M1-1-u5-C2',2,'blank','auto','15는 10개씩 묶음 (        )개와 낱개 5개예요.',ARRAY['M1-1-u5-X04','M1-1-u5-X05']::text[],true,'{"seq":8,"concept":"M1-1-u5-C2","difficulty":2,"kind":"blank","stem":"15는 10개씩 묶음 (        )개와 낱개 5개예요.","options":[{"t":"1","correct":true},{"t":"5","mis":"M1-1-u5-X04"},{"t":"10","mis":"M1-1-u5-X05"}],"explanation":["15의 앞자리 1은 묶음의 수예요.","10개씩 묶음 1개와 낱개 5개예요.","묶음은 몇 개인지 개수로 세어요."],"variant_rule":{"alt":[{"stem":"10개씩 묶음 1개와 낱개 (        )개는 19예요.","options":[{"t":"9","correct":true},{"t":"1","mis":"M1-1-u5-X04"},{"t":"19","mis":"M1-1-u5-X06"}],"explanation":["19의 뒷자리 9가 낱개의 수예요.","묶음 1개와 낱개 9개면 19예요.","낱개는 뒷자리에 써요."]},{"stem":"10개씩 묶음 1개와 낱개 (        )개는 12예요.","options":[{"t":"2","correct":true},{"t":"1","mis":"M1-1-u5-X04"},{"t":"12","mis":"M1-1-u5-X06"}],"explanation":["12의 뒷자리 2가 낱개의 수예요.","묶음 1개와 낱개 2개면 12예요.","낱개는 뒷자리에 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_basic#9','math',1,1,'u5','L04','g1_1_math_u5_L04_basic','lesson_basic','M1-1-u5-C2',2,'mc','auto','블록이 10개씩 묶음 1개와 낱개 8개 있어요. 블록은 모두 몇 개인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X05']::text[],true,'{"seq":9,"concept":"M1-1-u5-C2","difficulty":2,"kind":"mc","stem":"블록이 10개씩 묶음 1개와 낱개 8개 있어요. 블록은 모두 몇 개인가요?","options":[{"t":"18","correct":true},{"t":"81","mis":"M1-1-u5-X04"},{"t":"9","mis":"M1-1-u5-X05"}],"explanation":["묶음 1개는 10개예요.","10개와 낱개 8개를 더하면 18개예요.","묶음 하나를 1로 세지 않아요."],"asset":{"type":"bundle_ones","tens":1,"ones":8},"variant_rule":{"bundle":{"tens":[1,1],"ones":[1,9],"ask":"number","cap":50}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_basic#10','math',1,1,'u5','L04','g1_1_math_u5_L04_basic','lesson_basic','M1-1-u5-C2',3,'error','auto','친구들이 16에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u5-X02','M1-1-u5-X04','M1-1-u5-X06']::text[],true,'{"seq":10,"concept":"M1-1-u5-C2","difficulty":3,"kind":"error","stem":"친구들이 16에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도이: 16은 「열여섯」이라고도, 「열육」이라고도 읽어.","correct":true,"mis_target":"M1-1-u5-X02"},{"t":"하루: 16은 10개씩 묶음 1개와 낱개 6개야.","mis":"M1-1-u5-X04"},{"t":"서아: 낱개 16개를 10개씩 묶으면 묶음 1개와 낱개 6개야.","mis":"M1-1-u5-X06"}],"explanation":["16은 「십육」 또는 「열여섯」이라고 읽어요.","「열육」은 두 가지 읽기를 섞은 말이에요.","도이가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"친구들이 14에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우: 14는 낱개가 1개, 묶음이 4개야.","correct":true,"mis_target":"M1-1-u5-X04"},{"t":"유나: 14는 「열넷」이라고 읽어.","mis":"M1-1-u5-X02"},{"t":"하루: 14는 「십사」라고도 읽어.","mis":"M1-1-u5-X02"}],"explanation":["14의 앞자리 1은 묶음, 뒷자리 4는 낱개예요.","묶음 1개와 낱개 4개예요.","지우가 자리를 거꾸로 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_challenge#1','math',1,1,'u5','L04','g1_1_math_u5_L04_challenge','lesson_challenge','M1-1-u5-C2',2,'mc','auto','그림을 보세요. 낱개는 몇 개인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X06']::text[],true,'{"seq":1,"concept":"M1-1-u5-C2","difficulty":2,"kind":"mc","stem":"그림을 보세요. 낱개는 몇 개인가요?","options":[{"t":"6","correct":true},{"t":"1","mis":"M1-1-u5-X04"},{"t":"16","mis":"M1-1-u5-X06"}],"explanation":["10개씩 묶음 1개와 낱개 6개예요.","낱개는 6개예요.","묶음은 10개짜리, 낱개는 하나씩이에요."],"asset":{"type":"bundle_ones","tens":1,"ones":6},"variant_rule":{"bundle":{"tens":[1,1],"ones":[1,9],"ask":"ones","cap":50}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_challenge#2','math',1,1,'u5','L04','g1_1_math_u5_L04_challenge','lesson_challenge','M1-1-u5-C2',2,'sa','auto','「십칠」을 수로 쓰면 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M1-1-u5-C2","difficulty":2,"kind":"sa","stem":"「십칠」을 수로 쓰면 무엇인가요?","answer":["17"],"explanation":["「십칠」은 10개씩 묶음 1개와 낱개 7개예요.","수로 쓰면 17이에요.","묶음 수를 앞에, 낱개 수를 뒤에 붙여 써요."],"variant_rule":{"read2":{"range":[11,19],"ask":"num","way":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_challenge#3','math',1,1,'u5','L04','g1_1_math_u5_L04_challenge','lesson_challenge','M1-1-u5-C2',3,'mc','auto','10개씩 묶음 1개가 놓여 있어요. 18을 만들려면 낱개를 몇 개 더 놓아야 하나요?',ARRAY['M1-1-u5-X06','M1-1-u5-X04']::text[],true,'{"seq":3,"concept":"M1-1-u5-C2","difficulty":3,"kind":"mc","stem":"10개씩 묶음 1개가 놓여 있어요. 18을 만들려면 낱개를 몇 개 더 놓아야 하나요?","options":[{"t":"8","correct":true},{"t":"18","mis":"M1-1-u5-X06"},{"t":"81","mis":"M1-1-u5-X04"}],"explanation":["18은 10개씩 묶음 1개와 낱개 8개예요.","묶음 1개는 이미 있어요.","그래서 낱개 8개만 더 놓으면 돼요."],"variant_rule":{"alt":[{"stem":"10개씩 묶음 1개가 놓여 있어요. 13을 만들려면 낱개를 몇 개 더 놓아야 하나요?","options":[{"t":"3","correct":true},{"t":"13","mis":"M1-1-u5-X06"},{"t":"31","mis":"M1-1-u5-X04"}],"explanation":["13은 10개씩 묶음 1개와 낱개 3개예요.","묶음 1개는 이미 있어요.","그래서 낱개 3개만 더 놓으면 돼요."]},{"stem":"10개씩 묶음 1개가 놓여 있어요. 15를 만들려면 낱개를 몇 개 더 놓아야 하나요?","options":[{"t":"5","correct":true},{"t":"15","mis":"M1-1-u5-X06"},{"t":"6","mis":"M1-1-u5-X05"}],"explanation":["15는 10개씩 묶음 1개와 낱개 5개예요.","묶음 1개는 이미 있어요.","그래서 낱개 5개만 더 놓으면 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_challenge#4','math',1,1,'u5','L04','g1_1_math_u5_L04_challenge','lesson_challenge','M1-1-u5-C2',3,'mc','auto','낱개 14개가 있어요. 10개씩 묶으면 어떻게 되나요?',ARRAY['M1-1-u5-X06','M1-1-u5-X04']::text[],true,'{"seq":4,"concept":"M1-1-u5-C2","difficulty":3,"kind":"mc","stem":"낱개 14개가 있어요. 10개씩 묶으면 어떻게 되나요?","options":[{"t":"묶음 1개, 낱개 4개","correct":true},{"t":"묶음 0개, 낱개 14개","mis":"M1-1-u5-X06"},{"t":"묶음 4개, 낱개 1개","mis":"M1-1-u5-X04"}],"explanation":["14개 가운데 10개를 한 묶음으로 묶어요.","묶음 1개와 낱개 4개가 남아요.","낱개가 10개가 되면 묶어서 세어요."],"variant_rule":{"alt":[{"stem":"낱개 17개가 있어요. 10개씩 묶으면 어떻게 되나요?","options":[{"t":"묶음 1개, 낱개 7개","correct":true},{"t":"묶음 0개, 낱개 17개","mis":"M1-1-u5-X06"},{"t":"묶음 7개, 낱개 1개","mis":"M1-1-u5-X04"}],"explanation":["17개 가운데 10개를 한 묶음으로 묶어요.","묶음 1개와 낱개 7개가 남아요.","낱개가 10개가 되면 묶어서 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_challenge#5','math',1,1,'u5','L04','g1_1_math_u5_L04_challenge','lesson_challenge','M1-1-u5-C2',3,'ox','auto','「십오」와 「열다섯」은 같은 수예요.',ARRAY['M1-1-u5-X02']::text[],true,'{"seq":5,"concept":"M1-1-u5-C2","difficulty":3,"kind":"ox","stem":"「십오」와 「열다섯」은 같은 수예요.","answer":"O","reason_options":[{"t":"둘 다 10개씩 묶음 1개와 낱개 5개니까","correct":true},{"t":"읽는 말이 다르니 다른 수니까","mis":"M1-1-u5-X02"}],"mis":"M1-1-u5-X02","explanation":["「십오」도 15, 「열다섯」도 15예요.","한 수를 두 가지로 읽은 거예요.","그래서 같은 수예요."],"variant_rule":{"alt":[{"stem":"11과 12를 「열하나, 열둘」이라고 읽으면, 13은 「열삼」이라고 읽어요.","answer":"X","reason_options":[{"t":"「열」 다음에는 하나, 둘, 셋으로 이어 읽어 「열셋」이니까","correct":true},{"t":"숫자 3은 「삼」이니까","mis":"M1-1-u5-X02"}],"explanation":["「열하나, 열둘」로 읽기 시작했어요.","같은 읽기로 이어 가면 13은 「열셋」이에요.","「열삼」은 두 읽기를 섞은 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_challenge#6','math',1,1,'u5','L04','g1_1_math_u5_L04_challenge','lesson_challenge','M1-1-u5-C2',3,'mc','auto','나는 10개씩 묶음 1개와 낱개 몇 개인 수예요. 낱개는 5보다 크고 7보다 작아요. 나는 누구일까요?',ARRAY['M1-1-u5-X04','M1-1-u5-X13']::text[],true,'{"seq":6,"concept":"M1-1-u5-C2","difficulty":3,"kind":"mc","stem":"나는 10개씩 묶음 1개와 낱개 몇 개인 수예요. 낱개는 5보다 크고 7보다 작아요. 나는 누구일까요?","options":[{"t":"16","correct":true},{"t":"61","mis":"M1-1-u5-X04"},{"t":"17","mis":"M1-1-u5-X13"}],"explanation":["5보다 크고 7보다 작은 수는 6이에요.","묶음 1개와 낱개 6개 — 16이에요.","「~보다 크고 ~보다 작은」에는 양 끝 수가 들어가지 않아요."],"variant_rule":{"alt":[{"stem":"나는 10개씩 묶음 1개와 낱개 몇 개인 수예요. 낱개는 2보다 크고 4보다 작아요. 나는 누구일까요?","options":[{"t":"13","correct":true},{"t":"31","mis":"M1-1-u5-X04"},{"t":"14","mis":"M1-1-u5-X13"}],"explanation":["2보다 크고 4보다 작은 수는 3이에요.","묶음 1개와 낱개 3개 — 13이에요.","양 끝 수 2와 4는 들어가지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_challenge#7','math',1,1,'u5','L04','g1_1_math_u5_L04_challenge','lesson_challenge','M1-1-u5-C2',3,'match','auto','같은 수끼리 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u5-C2","difficulty":3,"kind":"match","stem":"같은 수끼리 이어 보세요.","pairs":[{"l":"묶음 1개, 낱개 2개","r":"열둘"},{"l":"묶음 1개, 낱개 9개","r":"십구"},{"l":"낱개 15개","r":"열다섯"}],"mis":"M1-1-u5-X06","explanation":["묶음 1개, 낱개 2개는 12 — 열둘이에요.","묶음 1개, 낱개 9개는 19 — 십구, 낱개 15개는 15 — 열다섯이에요.","낱개 15개도 묶으면 묶음 1개와 낱개 5개예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"낱개 11개","r":"십일"},{"l":"묶음 1개, 낱개 4개","r":"열넷"},{"l":"묶음 1개, 낱개 7개","r":"십칠"}],"explanation":["낱개 11개를 묶으면 묶음 1개와 낱개 1개 — 11이에요.","묶음 1개, 낱개 4개는 14, 묶음 1개, 낱개 7개는 17이에요.","읽는 말은 두 가지 가운데 하나로 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_challenge#8','math',1,1,'u5','L04','g1_1_math_u5_L04_challenge','lesson_challenge','M1-1-u5-C2',4,'mc','auto','블록이 10개씩 묶음 1개와 낱개 5개 있어요. 지우가 낱개 3개를 더 가져왔어요. 블록은 모두 몇 개이고, 어떻게 읽나요?',ARRAY['M1-1-u5-X02','M1-1-u5-X04']::text[],true,'{"seq":8,"concept":"M1-1-u5-C2","difficulty":4,"kind":"mc","stem":"블록이 10개씩 묶음 1개와 낱개 5개 있어요. 지우가 낱개 3개를 더 가져왔어요. 블록은 모두 몇 개이고, 어떻게 읽나요?","options":[{"t":"18 — 열여덟","correct":true},{"t":"18 — 열팔","mis":"M1-1-u5-X02"},{"t":"81 — 팔십일","mis":"M1-1-u5-X04"}],"explanation":["낱개가 5개에서 3개 늘어 8개가 되었어요.","묶음 1개와 낱개 8개 — 18이에요.","「열여덟」 또는 「십팔」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"블록이 10개씩 묶음 1개와 낱개 2개 있어요. 하루가 낱개 4개를 더 가져왔어요. 블록은 모두 몇 개이고, 어떻게 읽나요?","options":[{"t":"16 — 십육","correct":true},{"t":"16 — 열육","mis":"M1-1-u5-X02"},{"t":"61 — 육십일","mis":"M1-1-u5-X04"}],"explanation":["낱개가 2개에서 4개 늘어 6개가 되었어요.","묶음 1개와 낱개 6개 — 16이에요.","「십육」 또는 「열여섯」이라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_challenge#9','math',1,1,'u5','L04','g1_1_math_u5_L04_challenge','lesson_challenge','M1-1-u5-C2',4,'essay','teacher','13은 「십삼」이라고도 「열셋」이라고도 읽어요. 각각 어떤 때 쓰면 좋을지 예를 하나씩 들어 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-1-u5-C2","difficulty":4,"kind":"essay","stem":"13은 「십삼」이라고도 「열셋」이라고도 읽어요. 각각 어떤 때 쓰면 좋을지 예를 하나씩 들어 말해 보세요.","answer_guide":{"answer":"날짜나 번호처럼 차례·이름을 말할 때는 「십삼」(13일, 13번), 개수나 나이를 말할 때는 「열셋」(사탕 열세 개, 열세 살)으로 읽는다.","scoring_points":["「십삼」을 쓰는 알맞은 예를 들었는가","「열셋」을 쓰는 알맞은 예를 들었는가","두 읽기가 같은 수라는 것을 알고 있는가"]},"explanation":["13은 두 가지로 읽어요.","날짜·번호는 「십삼」, 개수·나이는 「열셋(열세)」으로 흔히 읽어요.","어떻게 읽어도 같은 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L04_challenge#10','math',1,1,'u5','L04','g1_1_math_u5_L04_challenge','lesson_challenge','M1-1-u5-C2',4,'mc','auto','수 카드 1, 6, 9 가운데 두 장을 골라 십몇을 만들려고 해요. 만들 수 있는 가장 큰 십몇은 무엇인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X16']::text[],true,'{"seq":10,"concept":"M1-1-u5-C2","difficulty":4,"kind":"mc","stem":"수 카드 1, 6, 9 가운데 두 장을 골라 십몇을 만들려고 해요. 만들 수 있는 가장 큰 십몇은 무엇인가요?","options":[{"t":"19","correct":true},{"t":"91","mis":"M1-1-u5-X04"},{"t":"16","mis":"M1-1-u5-X16"}],"explanation":["십몇은 앞자리가 1이에요.","뒷자리에 6과 9 가운데 큰 9를 놓아요.","가장 큰 십몇은 19예요."],"variant_rule":{"alt":[{"stem":"수 카드 1, 4, 7 가운데 두 장을 골라 십몇을 만들려고 해요. 만들 수 있는 가장 작은 십몇은 무엇인가요?","options":[{"t":"14","correct":true},{"t":"41","mis":"M1-1-u5-X04"},{"t":"17","mis":"M1-1-u5-X16"}],"explanation":["십몇은 앞자리가 1이에요.","뒷자리에 4와 7 가운데 작은 4를 놓아요.","가장 작은 십몇은 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_basic#1','math',1,1,'u5','L05','g1_1_math_u5_L05_basic','lesson_basic','M1-1-u5-C3',1,'mc','auto','9와 6을 모으면 얼마인가요?',ARRAY['M1-1-u5-X08']::text[],true,'{"seq":1,"concept":"M1-1-u5-C3","difficulty":1,"kind":"mc","stem":"9와 6을 모으면 얼마인가요?","options":[{"t":"15","correct":true},{"t":"14","mis":"M1-1-u5-X08"},{"t":"16","mis":"M1-1-u5-X08"}],"explanation":["큰 수 9를 머리에 두어요.","10, 11, 12, 13, 14, 15 — 6번 이어 세면 15예요.","모으기는 큰 수부터 이어 세면 빨라요."],"asset":{"type":"number_bond","whole":null,"parts":[9,6]},"variant_rule":{"bond":{"whole":[11,18],"ask":"whole","part_max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_basic#2','math',1,1,'u5','L05','g1_1_math_u5_L05_basic','lesson_basic','M1-1-u5-C3',1,'sa','auto','14를 두 수로 가르기 했어요. 8 옆의 빈칸에 알맞은 수는 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M1-1-u5-C3","difficulty":1,"kind":"sa","stem":"14를 두 수로 가르기 했어요. 8 옆의 빈칸에 알맞은 수는 무엇인가요?","answer":["6"],"explanation":["14를 둘로 갈랐어요.","8에서 14까지 이어 세면 9, 10, 11, 12, 13, 14 — 6이에요.","가른 두 수를 모으면 다시 14가 돼요."],"asset":{"type":"number_bond","whole":14,"parts":[8,null]},"variant_rule":{"bond":{"whole":[11,18],"ask":"part","part_max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_basic#3','math',1,1,'u5','L05','g1_1_math_u5_L05_basic','lesson_basic','M1-1-u5-C3',1,'mc','auto','16을 두 수로 가르기 했어요. 9 옆의 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M1-1-u5-X03','M1-1-u5-X09']::text[],true,'{"seq":3,"concept":"M1-1-u5-C3","difficulty":1,"kind":"mc","stem":"16을 두 수로 가르기 했어요. 9 옆의 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"7","correct":true},{"t":"9","mis":"M1-1-u5-X03"},{"t":"16","mis":"M1-1-u5-X09"}],"explanation":["16을 둘로 갈랐어요.","9를 뺀 나머지는 7이에요.","9와 7을 모으면 다시 16이 돼요."],"asset":{"type":"number_bond","whole":16,"parts":[9,null]},"variant_rule":{"bond":{"whole":[11,18],"ask":"part","part_max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_basic#4','math',1,1,'u5','L05','g1_1_math_u5_L05_basic','lesson_basic','M1-1-u5-C3',1,'mc','auto','큰 수 8부터 이어 세어 8과 5를 모으려고 해요. 바르게 센 것은 어느 것인가요?',ARRAY['M1-1-u5-X08']::text[],true,'{"seq":4,"concept":"M1-1-u5-C3","difficulty":1,"kind":"mc","stem":"큰 수 8부터 이어 세어 8과 5를 모으려고 해요. 바르게 센 것은 어느 것인가요?","options":[{"t":"8 다음부터 9, 10, 11, 12, 13","correct":true},{"t":"8부터 8, 9, 10, 11, 12","mis":"M1-1-u5-X08"},{"t":"8 다음부터 9, 10, 11, 12","mis":"M1-1-u5-X08"}],"explanation":["8은 머리에 두고 다음 수 9부터 세어요.","5번 세면 9, 10, 11, 12, 13 — 13이에요.","시작 수를 한 번 더 세면 하나 적게 나와요."],"variant_rule":{"alt":[{"stem":"큰 수 7부터 이어 세어 7과 6을 모으려고 해요. 바르게 센 것은 어느 것인가요?","options":[{"t":"7 다음부터 8, 9, 10, 11, 12, 13","correct":true},{"t":"7부터 7, 8, 9, 10, 11, 12","mis":"M1-1-u5-X08"},{"t":"7 다음부터 8, 9, 10, 11, 12","mis":"M1-1-u5-X08"}],"explanation":["7은 머리에 두고 다음 수 8부터 세어요.","6번 세면 8, 9, 10, 11, 12, 13 — 13이에요.","몇 번 셌는지 손가락으로 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_basic#5','math',1,1,'u5','L05','g1_1_math_u5_L05_basic','lesson_basic','M1-1-u5-C3',2,'mc','auto','조개 7개와 조개 6개를 모으면 조개는 모두 몇 개인가요?',ARRAY['M1-1-u5-X08','M1-1-u5-X09']::text[],true,'{"seq":5,"concept":"M1-1-u5-C3","difficulty":2,"kind":"mc","stem":"조개 7개와 조개 6개를 모으면 조개는 모두 몇 개인가요?","options":[{"t":"13","correct":true},{"t":"12","mis":"M1-1-u5-X08"},{"t":"1","mis":"M1-1-u5-X09"}],"explanation":["큰 수 7을 머리에 두어요.","8, 9, 10, 11, 12, 13 — 13개예요.","모으기는 두 수를 합치는 거예요."],"variant_rule":{"alt":[{"stem":"구슬 8개와 구슬 9개를 모으면 구슬은 모두 몇 개인가요?","options":[{"t":"17","correct":true},{"t":"16","mis":"M1-1-u5-X08"},{"t":"1","mis":"M1-1-u5-X09"}],"explanation":["큰 수 9를 머리에 두어요.","10부터 8번 이어 세면 17이에요.","모으기는 두 수를 합치는 거예요."]},{"stem":"딸기 5개와 딸기 9개를 모으면 딸기는 모두 몇 개인가요?","options":[{"t":"14","correct":true},{"t":"15","mis":"M1-1-u5-X08"},{"t":"4","mis":"M1-1-u5-X09"}],"explanation":["큰 수 9를 머리에 두어요.","10, 11, 12, 13, 14 — 14개예요.","모으기는 두 수를 합치는 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_basic#6','math',1,1,'u5','L05','g1_1_math_u5_L05_basic','lesson_basic','M1-1-u5-C3',2,'ox','auto','13은 6과 7로 가를 수 있어요.',ARRAY['M1-1-u5-X03']::text[],true,'{"seq":6,"concept":"M1-1-u5-C3","difficulty":2,"kind":"ox","stem":"13은 6과 7로 가를 수 있어요.","answer":"O","reason_options":[{"t":"6과 7을 모으면 13이니까","correct":true},{"t":"13은 1과 3으로만 가를 수 있으니까","mis":"M1-1-u5-X03"}],"mis":"M1-1-u5-X03","explanation":["6과 7을 모아 보아요.","7부터 6번 이어 세면 13이에요.","그래서 13은 6과 7로 가를 수 있어요."],"variant_rule":{"alt":[{"stem":"15는 8과 6으로 가를 수 있어요.","answer":"X","reason_options":[{"t":"8과 6을 모으면 14니까","correct":true},{"t":"8과 6은 둘 다 15보다 작으니까","mis":"M1-1-u5-X03"}],"explanation":["8과 6을 모아 보아요.","8부터 6번 이어 세면 14예요.","15가 되려면 8과 7이어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_basic#7','math',1,1,'u5','L05','g1_1_math_u5_L05_basic','lesson_basic','M1-1-u5-C3',2,'match','auto','모아서 13이 되는 두 수끼리 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u5-C3","difficulty":2,"kind":"match","stem":"모아서 13이 되는 두 수끼리 이어 보세요.","pairs":[{"l":"4","r":"9"},{"l":"5","r":"8"},{"l":"6","r":"7"}],"mis":"M1-1-u5-X03","explanation":["4와 9를 모으면 13이에요.","5와 8, 6과 7도 모으면 13이에요.","모은 수가 13이 되는지 확인해요."],"variant_rule":{"alt":[{"stem":"모아서 15가 되는 두 수끼리 이어 보세요.","pairs":[{"l":"6","r":"9"},{"l":"7","r":"8"},{"l":"8","r":"7"}],"explanation":["6과 9를 모으면 15예요.","7과 8, 8과 7도 모으면 15예요.","모은 수가 15가 되는지 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_basic#8','math',1,1,'u5','L05','g1_1_math_u5_L05_basic','lesson_basic','M1-1-u5-C3',2,'blank','auto','17은 9와 (        )로 가를 수 있어요.',ARRAY['M1-1-u5-X03','M1-1-u5-X09']::text[],true,'{"seq":8,"concept":"M1-1-u5-C3","difficulty":2,"kind":"blank","stem":"17은 9와 (        )로 가를 수 있어요.","options":[{"t":"8","correct":true},{"t":"7","mis":"M1-1-u5-X03"},{"t":"26","mis":"M1-1-u5-X09"}],"explanation":["9에서 17까지 이어 세어요.","10, 11, 12, 13, 14, 15, 16, 17 — 8이에요.","9와 8을 모으면 17이에요."],"variant_rule":{"alt":[{"stem":"11은 4와 (        )로 가를 수 있어요.","options":[{"t":"7","correct":true},{"t":"6","mis":"M1-1-u5-X03"},{"t":"15","mis":"M1-1-u5-X09"}],"explanation":["4에서 11까지 이어 세어요.","5, 6, 7, 8, 9, 10, 11 — 7이에요.","4와 7을 모으면 11이에요."]},{"stem":"12는 (        )와 3으로 가를 수 있어요.","options":[{"t":"9","correct":true},{"t":"8","mis":"M1-1-u5-X03"},{"t":"15","mis":"M1-1-u5-X09"}],"explanation":["3에서 12까지 이어 세어요.","4부터 12까지 9번 세어요.","9와 3을 모으면 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_basic#9','math',1,1,'u5','L05','g1_1_math_u5_L05_basic','lesson_basic','M1-1-u5-C3',2,'mc','auto','14를 두 수로 가르는 방법이 아닌 것은 어느 것인가요?',ARRAY['M1-1-u5-X03']::text[],true,'{"seq":9,"concept":"M1-1-u5-C3","difficulty":2,"kind":"mc","stem":"14를 두 수로 가르는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"7과 8","correct":true},{"t":"5와 9","mis":"M1-1-u5-X03"},{"t":"6과 8","mis":"M1-1-u5-X03"}],"explanation":["5와 9, 6과 8은 모으면 14예요.","7과 8을 모으면 15예요.","그래서 「7과 8」은 14를 가른 것이 아니에요."],"variant_rule":{"alt":[{"stem":"12를 두 수로 가르는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"4와 9","correct":true},{"t":"3과 9","mis":"M1-1-u5-X03"},{"t":"5와 7","mis":"M1-1-u5-X03"}],"explanation":["3과 9, 5와 7은 모으면 12예요.","4와 9를 모으면 13이에요.","그래서 「4와 9」는 12를 가른 것이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_basic#10','math',1,1,'u5','L05','g1_1_math_u5_L05_basic','lesson_basic','M1-1-u5-C3',3,'sa','auto','15를 한 자리 수 두 개로 가르는 방법은 모두 몇 가지인가요? (6과 9와 9와 6은 다른 방법으로 세어요.)','{}'::text[],false,'{"seq":10,"concept":"M1-1-u5-C3","difficulty":3,"kind":"sa","stem":"15를 한 자리 수 두 개로 가르는 방법은 모두 몇 가지인가요? (6과 9와 9와 6은 다른 방법으로 세어요.)","answer":["4"],"explanation":["6과 9, 7과 8, 8과 7, 9와 6이에요.","5와 10처럼 두 자리 수가 나오면 안 돼요.","그래서 모두 4가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_challenge#1','math',1,1,'u5','L05','g1_1_math_u5_L05_challenge','lesson_challenge','M1-1-u5-C3',2,'mc','auto','8과 7을 모으면 얼마인가요?',ARRAY['M1-1-u5-X08']::text[],true,'{"seq":1,"concept":"M1-1-u5-C3","difficulty":2,"kind":"mc","stem":"8과 7을 모으면 얼마인가요?","options":[{"t":"15","correct":true},{"t":"14","mis":"M1-1-u5-X08"},{"t":"16","mis":"M1-1-u5-X08"}],"explanation":["큰 수 8을 머리에 두어요.","9, 10, 11, 12, 13, 14, 15 — 15예요.","이어 셀 때는 시작 수를 다시 세지 않아요."],"asset":{"type":"number_bond","whole":null,"parts":[8,7]},"variant_rule":{"bond":{"whole":[11,18],"ask":"whole","part_max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_challenge#2','math',1,1,'u5','L05','g1_1_math_u5_L05_challenge','lesson_challenge','M1-1-u5-C3',2,'sa','auto','12를 두 수로 가르기 했어요. 5 옆의 빈칸에 알맞은 수는 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M1-1-u5-C3","difficulty":2,"kind":"sa","stem":"12를 두 수로 가르기 했어요. 5 옆의 빈칸에 알맞은 수는 무엇인가요?","answer":["7"],"explanation":["12를 둘로 갈랐어요.","5에서 12까지 이어 세면 7이에요.","5와 7을 모으면 12예요."],"asset":{"type":"number_bond","whole":12,"parts":[5,null]},"variant_rule":{"bond":{"whole":[11,18],"ask":"part","part_max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_challenge#3','math',1,1,'u5','L05','g1_1_math_u5_L05_challenge','lesson_challenge','M1-1-u5-C3',3,'mc','auto','조개 16개를 두 어항에 나누어 넣었어요. 한 어항에 9개를 넣으면 다른 어항에는 몇 개를 넣어야 하나요?',ARRAY['M1-1-u5-X03','M1-1-u5-X09']::text[],true,'{"seq":3,"concept":"M1-1-u5-C3","difficulty":3,"kind":"mc","stem":"조개 16개를 두 어항에 나누어 넣었어요. 한 어항에 9개를 넣으면 다른 어항에는 몇 개를 넣어야 하나요?","options":[{"t":"7","correct":true},{"t":"9","mis":"M1-1-u5-X03"},{"t":"25","mis":"M1-1-u5-X09"}],"explanation":["16을 9와 몇으로 가르는지 찾아요.","9에서 16까지 이어 세면 7이에요.","다른 어항에는 7개를 넣어요."],"variant_rule":{"alt":[{"stem":"조개 13개를 두 어항에 나누어 넣었어요. 한 어항에 8개를 넣으면 다른 어항에는 몇 개를 넣어야 하나요?","options":[{"t":"5","correct":true},{"t":"6","mis":"M1-1-u5-X03"},{"t":"21","mis":"M1-1-u5-X09"}],"explanation":["13을 8과 몇으로 가르는지 찾아요.","8에서 13까지 이어 세면 5예요.","다른 어항에는 5개를 넣어요."]},{"stem":"조개 11개를 두 어항에 나누어 넣었어요. 한 어항에 6개를 넣으면 다른 어항에는 몇 개를 넣어야 하나요?","options":[{"t":"5","correct":true},{"t":"6","mis":"M1-1-u5-X03"},{"t":"17","mis":"M1-1-u5-X09"}],"explanation":["11을 6과 몇으로 가르는지 찾아요.","6에서 11까지 이어 세면 5예요.","다른 어항에는 5개를 넣어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_challenge#4','math',1,1,'u5','L05','g1_1_math_u5_L05_challenge','lesson_challenge','M1-1-u5-C3',3,'error','auto','지우가 9와 5를 모으며 이렇게 셌어요. 「9, 10, 11, 12, 13 — 13이야!」 지우는 무엇을 잘못했나요?',ARRAY['M1-1-u5-X08']::text[],true,'{"seq":4,"concept":"M1-1-u5-C3","difficulty":3,"kind":"error","stem":"지우가 9와 5를 모으며 이렇게 셌어요. 「9, 10, 11, 12, 13 — 13이야!」 지우는 무엇을 잘못했나요?","options":[{"t":"시작 수 9까지 세어서 하나 적게 셌어요","correct":true,"mis_target":"M1-1-u5-X08"},{"t":"정말 13이에요","mis":"M1-1-u5-X08"},{"t":"작은 수 5부터 세어야 해요","mis":"M1-1-u5-X08"}],"explanation":["9는 머리에 두고 다음 수 10부터 세어야 해요.","10, 11, 12, 13, 14 — 5번 세면 14예요.","지우는 9를 한 번 더 세어서 하나 적게 나왔어요."],"variant_rule":{"alt":[{"stem":"하루가 7과 6을 모으며 이렇게 셌어요. 「7, 8, 9, 10, 11, 12 — 12야!」 하루는 무엇을 잘못했나요?","options":[{"t":"시작 수 7까지 세어서 하나 적게 셌어요","correct":true,"mis_target":"M1-1-u5-X08"},{"t":"정말 12예요","mis":"M1-1-u5-X08"},{"t":"작은 수 6부터 세어야 해요","mis":"M1-1-u5-X08"}],"explanation":["7은 머리에 두고 다음 수 8부터 세어야 해요.","8, 9, 10, 11, 12, 13 — 6번 세면 13이에요.","하루는 7을 한 번 더 세어서 하나 적게 나왔어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_challenge#5','math',1,1,'u5','L05','g1_1_math_u5_L05_challenge','lesson_challenge','M1-1-u5-C3',3,'mc','auto','모아서 14가 되는 두 한 자리 수 가운데 두 수가 같은 것은 어느 것인가요?',ARRAY['M1-1-u5-X03']::text[],true,'{"seq":5,"concept":"M1-1-u5-C3","difficulty":3,"kind":"mc","stem":"모아서 14가 되는 두 한 자리 수 가운데 두 수가 같은 것은 어느 것인가요?","options":[{"t":"7과 7","correct":true},{"t":"1과 4","mis":"M1-1-u5-X03"},{"t":"6과 8","mis":"M1-1-u5-X03"}],"explanation":["같은 두 수를 모아 14가 되는 것을 찾아요.","7과 7을 모으면 14예요.","1과 4는 숫자를 떼어 놓은 것일 뿐 모으면 5예요."],"variant_rule":{"alt":[{"stem":"모아서 16이 되는 두 한 자리 수 가운데 두 수가 같은 것은 어느 것인가요?","options":[{"t":"8과 8","correct":true},{"t":"1과 6","mis":"M1-1-u5-X03"},{"t":"7과 9","mis":"M1-1-u5-X03"}],"explanation":["같은 두 수를 모아 16이 되는 것을 찾아요.","8과 8을 모으면 16이에요.","1과 6은 숫자를 떼어 놓은 것일 뿐 모으면 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_challenge#6','math',1,1,'u5','L05','g1_1_math_u5_L05_challenge','lesson_challenge','M1-1-u5-C3',3,'ox','auto','두 수를 모아 십몇을 만들 때는 큰 수부터 이어 세는 것이 더 빨라요.',ARRAY['M1-1-u5-X08']::text[],true,'{"seq":6,"concept":"M1-1-u5-C3","difficulty":3,"kind":"ox","stem":"두 수를 모아 십몇을 만들 때는 큰 수부터 이어 세는 것이 더 빨라요.","answer":"O","reason_options":[{"t":"큰 수는 머리에 두고 작은 수만큼만 세면 되니까","correct":true},{"t":"작은 수부터 세어야 답이 맞으니까","mis":"M1-1-u5-X08"}],"mis":"M1-1-u5-X08","explanation":["9와 4를 모을 때 9부터 세면 4번만 세면 돼요.","4부터 세면 9번이나 세야 해요.","어느 쪽이든 답은 같지만 큰 수부터가 빨라요."],"variant_rule":{"alt":[{"stem":"6과 9를 모을 때 9부터 이어 세면 6부터 이어 셀 때와 답이 달라요.","answer":"X","reason_options":[{"t":"어느 수부터 세어도 모은 수는 같으니까","correct":true},{"t":"시작하는 수가 다르면 답도 달라지니까","mis":"M1-1-u5-X08"}],"explanation":["9부터 세면 10, 11, 12, 13, 14, 15 — 15예요.","6부터 세어도 15예요.","모으는 차례를 바꾸어도 답은 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_challenge#7','math',1,1,'u5','L05','g1_1_math_u5_L05_challenge','lesson_challenge','M1-1-u5-C3',3,'mc','auto','□와 △를 모으면 13이에요. □가 △보다 3 더 커요. □는 얼마인가요?',ARRAY['M1-1-u5-X16','M1-1-u5-X03']::text[],true,'{"seq":7,"concept":"M1-1-u5-C3","difficulty":3,"kind":"mc","stem":"□와 △를 모으면 13이에요. □가 △보다 3 더 커요. □는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"5","mis":"M1-1-u5-X16"},{"t":"10","mis":"M1-1-u5-X03"}],"explanation":["13을 가르는 방법 가운데 차이가 3인 것을 찾아요.","8과 5 — 모으면 13, 차이는 3이에요.","□가 더 크니까 □는 8이에요."],"variant_rule":{"alt":[{"stem":"□와 △를 모으면 15예요. □가 △보다 1 더 커요. □는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"7","mis":"M1-1-u5-X16"},{"t":"9","mis":"M1-1-u5-X03"}],"explanation":["15를 가르는 방법 가운데 차이가 1인 것을 찾아요.","8과 7 — 모으면 15, 차이는 1이에요.","□가 더 크니까 □는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_challenge#8','math',1,1,'u5','L05','g1_1_math_u5_L05_challenge','lesson_challenge','M1-1-u5-C3',4,'mc','auto','15부터 3만큼 거꾸로 세면 어떤 수가 되나요?',ARRAY['M1-1-u5-X08','M1-1-u5-X10']::text[],true,'{"seq":8,"concept":"M1-1-u5-C3","difficulty":4,"kind":"mc","stem":"15부터 3만큼 거꾸로 세면 어떤 수가 되나요?","options":[{"t":"12","correct":true},{"t":"13","mis":"M1-1-u5-X08"},{"t":"18","mis":"M1-1-u5-X10"}],"explanation":["15를 머리에 두고 앞의 수로 세어요.","14, 13, 12 — 3번 세면 12예요.","거꾸로 셀 때도 시작 수는 다시 세지 않아요."],"variant_rule":{"alt":[{"stem":"17부터 4만큼 거꾸로 세면 어떤 수가 되나요?","options":[{"t":"13","correct":true},{"t":"14","mis":"M1-1-u5-X08"},{"t":"21","mis":"M1-1-u5-X10"}],"explanation":["17을 머리에 두고 앞의 수로 세어요.","16, 15, 14, 13 — 4번 세면 13이에요.","거꾸로 셀 때도 시작 수는 다시 세지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_challenge#9','math',1,1,'u5','L05','g1_1_math_u5_L05_challenge','lesson_challenge','M1-1-u5-C3',4,'essay','teacher','13을 두 수로 가르는 서로 다른 방법을 두 가지 쓰고, 가른 것이 맞는지 어떻게 확인할 수 있는지 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-1-u5-C3","difficulty":4,"kind":"essay","stem":"13을 두 수로 가르는 서로 다른 방법을 두 가지 쓰고, 가른 것이 맞는지 어떻게 확인할 수 있는지 말해 보세요.","answer_guide":{"answer":"예: 6과 7, 9와 4. 가른 두 수를 다시 모아(큰 수부터 이어 세어) 13이 되는지 확인한다.","scoring_points":["서로 다른 가르기를 두 가지 바르게 썼는가","다시 모아 확인한다는 방법을 말했는가","이어 세기 등 확인 과정을 구체적으로 말했는가"]},"explanation":["13은 6과 7, 9와 4, 8과 5 … 로 가를 수 있어요.","가른 두 수를 다시 모아 보면 돼요.","모은 수가 13이면 바르게 가른 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L05_challenge#10','math',1,1,'u5','L05','g1_1_math_u5_L05_challenge','lesson_challenge','M1-1-u5-C3',4,'mc','auto','빨간 주머니에 구슬 9개, 파란 주머니에 구슬 4개가 있어요. 파란 주머니의 구슬을 옮겨 빨간 주머니를 꼭 10개로 만들면 파란 주머니에는 몇 개가 남나요?',ARRAY['M1-1-u5-X09','M1-1-u5-X03']::text[],true,'{"seq":10,"concept":"M1-1-u5-C3","difficulty":4,"kind":"mc","stem":"빨간 주머니에 구슬 9개, 파란 주머니에 구슬 4개가 있어요. 파란 주머니의 구슬을 옮겨 빨간 주머니를 꼭 10개로 만들면 파란 주머니에는 몇 개가 남나요?","options":[{"t":"3","correct":true},{"t":"1","mis":"M1-1-u5-X09"},{"t":"4","mis":"M1-1-u5-X03"}],"explanation":["빨간 주머니가 10개가 되려면 1개를 옮겨야 해요.","파란 주머니에는 4개 가운데 3개가 남아요.","9와 4를 모은 13은 10과 3이에요."],"variant_rule":{"alt":[{"stem":"빨간 주머니에 구슬 8개, 파란 주머니에 구슬 7개가 있어요. 파란 주머니의 구슬을 옮겨 빨간 주머니를 꼭 10개로 만들면 파란 주머니에는 몇 개가 남나요?","options":[{"t":"5","correct":true},{"t":"2","mis":"M1-1-u5-X09"},{"t":"7","mis":"M1-1-u5-X03"}],"explanation":["빨간 주머니가 10개가 되려면 2개를 옮겨야 해요.","파란 주머니에는 7개 가운데 5개가 남아요.","8과 7을 모은 15는 10과 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_basic#1','math',1,1,'u5','L06','g1_1_math_u5_L06_basic','lesson_basic','M1-1-u5-C4',1,'mc','auto','10개씩 묶음 3개는 얼마인가요?',ARRAY['M1-1-u5-X05','M1-1-u5-X07']::text[],true,'{"seq":1,"concept":"M1-1-u5-C4","difficulty":1,"kind":"mc","stem":"10개씩 묶음 3개는 얼마인가요?","options":[{"t":"30","correct":true},{"t":"3","mis":"M1-1-u5-X05"},{"t":"300","mis":"M1-1-u5-X07"}],"explanation":["묶음 하나는 10이에요.","10, 20, 30 — 묶음 3개는 30이에요.","낱개가 없어도 0을 써서 자리를 지켜요."],"asset":{"type":"bundle_ones","tens":3,"ones":0},"variant_rule":{"alt":[{"stem":"10개씩 묶음 2개는 얼마인가요?","options":[{"t":"20","correct":true},{"t":"2","mis":"M1-1-u5-X05"},{"t":"200","mis":"M1-1-u5-X07"}],"explanation":["묶음 하나는 10이에요.","10, 20 — 묶음 2개는 20이에요.","낱개가 없어도 0을 써요."],"asset":{"type":"bundle_ones","tens":2,"ones":0}},{"stem":"10개씩 묶음 4개는 얼마인가요?","options":[{"t":"40","correct":true},{"t":"4","mis":"M1-1-u5-X05"},{"t":"14","mis":"M1-1-u5-X04"}],"explanation":["묶음 하나는 10이에요.","10, 20, 30, 40 — 묶음 4개는 40이에요.","낱개가 없어도 0을 써요."],"asset":{"type":"bundle_ones","tens":4,"ones":0}},{"stem":"10개씩 묶음 5개는 얼마인가요?","options":[{"t":"50","correct":true},{"t":"5","mis":"M1-1-u5-X05"},{"t":"15","mis":"M1-1-u5-X04"}],"explanation":["묶음 하나는 10이에요.","10, 20, 30, 40, 50 — 묶음 5개는 50이에요.","낱개가 없어도 0을 써요."],"asset":{"type":"bundle_ones","tens":5,"ones":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_basic#2','math',1,1,'u5','L06','g1_1_math_u5_L06_basic','lesson_basic','M1-1-u5-C4',1,'sa','auto','그림을 보세요. 10개씩 묶음은 몇 개인가요?','{}'::text[],true,'{"seq":2,"concept":"M1-1-u5-C4","difficulty":1,"kind":"sa","stem":"그림을 보세요. 10개씩 묶음은 몇 개인가요?","answer":["4"],"explanation":["10개씩 묶음 4개와 낱개 0개예요.","묶음은 4개예요.","묶음은 10개짜리예요."],"asset":{"type":"bundle_ones","tens":4,"ones":0},"variant_rule":{"bundle":{"tens":[2,5],"ones":[0,0],"ask":"tens","cap":50}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_basic#3','math',1,1,'u5','L06','g1_1_math_u5_L06_basic','lesson_basic','M1-1-u5-C4',1,'mc','auto','20을 바르게 읽은 것은 어느 것인가요?',ARRAY['M1-1-u5-X02','M1-1-u5-X05']::text[],true,'{"seq":3,"concept":"M1-1-u5-C4","difficulty":1,"kind":"mc","stem":"20을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"스물","correct":true},{"t":"둘십","mis":"M1-1-u5-X02"},{"t":"서른","mis":"M1-1-u5-X05"}],"explanation":["20은 10개씩 묶음 2개예요.","「이십」 또는 「스물」이라고 읽어요.","「둘십」처럼 두 읽기를 섞지 않아요."],"variant_rule":{"read2":{"range":[20,50],"ask":"read","way":"both","step10":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_basic#4','math',1,1,'u5','L06','g1_1_math_u5_L06_basic','lesson_basic','M1-1-u5-C4',1,'mc','auto','「마흔」을 수로 쓰면 무엇인가요?',ARRAY['M1-1-u5-X05','M1-1-u5-X07']::text[],true,'{"seq":4,"concept":"M1-1-u5-C4","difficulty":1,"kind":"mc","stem":"「마흔」을 수로 쓰면 무엇인가요?","options":[{"t":"40","correct":true},{"t":"50","mis":"M1-1-u5-X05"},{"t":"4","mis":"M1-1-u5-X07"}],"explanation":["「마흔」은 10개씩 묶음 4개예요.","수로 쓰면 40이에요.","낱개가 없으면 뒤에 0을 써요."],"variant_rule":{"read2":{"range":[20,50],"ask":"num","way":"both","step10":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_basic#5','math',1,1,'u5','L06','g1_1_math_u5_L06_basic','lesson_basic','M1-1-u5-C4',2,'mc','auto','튜브가 10개씩 묶음 2개 있어요. 10개씩 묶음 2개를 더 가져오면 튜브는 모두 몇 개인가요?',ARRAY['M1-1-u5-X07','M1-1-u5-X05']::text[],true,'{"seq":5,"concept":"M1-1-u5-C4","difficulty":2,"kind":"mc","stem":"튜브가 10개씩 묶음 2개 있어요. 10개씩 묶음 2개를 더 가져오면 튜브는 모두 몇 개인가요?","options":[{"t":"40","correct":true},{"t":"4","mis":"M1-1-u5-X07"},{"t":"22","mis":"M1-1-u5-X05"}],"explanation":["묶음이 2개에서 2개 늘어 4개가 되었어요.","10개씩 묶음 4개는 40이에요.","묶음 수를 먼저 세고 몇십으로 바꾸어요."],"variant_rule":{"alt":[{"stem":"구명조끼가 10개씩 묶음 3개 있어요. 10개씩 묶음 2개를 더 가져오면 구명조끼는 모두 몇 개인가요?","options":[{"t":"50","correct":true},{"t":"5","mis":"M1-1-u5-X07"},{"t":"32","mis":"M1-1-u5-X05"}],"explanation":["묶음이 3개에서 2개 늘어 5개가 되었어요.","10개씩 묶음 5개는 50이에요.","묶음 수를 먼저 세고 몇십으로 바꾸어요."]},{"stem":"공이 10개씩 묶음 4개 있어요. 10개씩 묶음 1개를 덜어 내면 공은 몇 개 남나요?","options":[{"t":"30","correct":true},{"t":"3","mis":"M1-1-u5-X07"},{"t":"39","mis":"M1-1-u5-X05"}],"explanation":["묶음이 4개에서 1개 줄어 3개가 되었어요.","10개씩 묶음 3개는 30이에요.","묶음 하나는 1개가 아니라 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_basic#6','math',1,1,'u5','L06','g1_1_math_u5_L06_basic','lesson_basic','M1-1-u5-C4',2,'ox','auto','50은 10개씩 묶음 5개예요.',ARRAY['M1-1-u5-X04']::text[],true,'{"seq":6,"concept":"M1-1-u5-C4","difficulty":2,"kind":"ox","stem":"50은 10개씩 묶음 5개예요.","answer":"O","reason_options":[{"t":"10, 20, 30, 40, 50 — 묶음을 5번 세니까","correct":true},{"t":"50에는 낱개가 5개 있으니까","mis":"M1-1-u5-X04"}],"mis":"M1-1-u5-X04","explanation":["10씩 세어 보아요 — 10, 20, 30, 40, 50.","묶음 5개가 50이에요.","50의 5는 묶음의 수예요."],"variant_rule":{"alt":[{"stem":"30은 낱개 3개예요.","answer":"X","reason_options":[{"t":"30은 10개씩 묶음 3개니까","correct":true},{"t":"30의 3은 낱개를 나타내니까","mis":"M1-1-u5-X04"}],"explanation":["30의 앞자리 3은 묶음의 수예요.","30은 10개씩 묶음 3개 — 낱개는 0개예요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_basic#7','math',1,1,'u5','L06','g1_1_math_u5_L06_basic','lesson_basic','M1-1-u5-C4',2,'match','auto','수와 읽는 말을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u5-C4","difficulty":2,"kind":"match","stem":"수와 읽는 말을 알맞게 이어 보세요.","pairs":[{"l":"20","r":"이십"},{"l":"30","r":"서른"},{"l":"40","r":"사십"}],"mis":"M1-1-u5-X02","explanation":["20은 이십 또는 스물이에요.","30은 삼십 또는 서른, 40은 사십 또는 마흔이에요.","몇십도 두 가지로 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 수와 읽는 말을 알맞게 이어 보세요.","pairs":[{"l":"50","r":"쉰"},{"l":"20","r":"스물"},{"l":"40","r":"마흔"}],"explanation":["50은 쉰 또는 오십이에요.","20은 스물, 40은 마흔이라고도 읽어요.","몇십도 두 가지로 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_basic#8','math',1,1,'u5','L06','g1_1_math_u5_L06_basic','lesson_basic','M1-1-u5-C4',2,'blank','auto','10개씩 묶음 (        )개는 50이에요.',ARRAY['M1-1-u5-X05','M1-1-u5-X04']::text[],true,'{"seq":8,"concept":"M1-1-u5-C4","difficulty":2,"kind":"blank","stem":"10개씩 묶음 (        )개는 50이에요.","options":[{"t":"5","correct":true},{"t":"50","mis":"M1-1-u5-X05"},{"t":"0","mis":"M1-1-u5-X04"}],"explanation":["50의 앞자리 5가 묶음의 수예요.","10개씩 묶음 5개는 50이에요.","묶음은 몇 개인지 개수로 세어요."],"variant_rule":{"alt":[{"stem":"10개씩 묶음 2개는 (        )예요.","options":[{"t":"20","correct":true},{"t":"2","mis":"M1-1-u5-X07"},{"t":"12","mis":"M1-1-u5-X05"}],"explanation":["묶음 하나는 10이에요.","묶음 2개는 20이에요.","낱개가 없으면 0을 써요."]},{"stem":"10개씩 묶음 (        )개는 30이에요.","options":[{"t":"3","correct":true},{"t":"30","mis":"M1-1-u5-X05"},{"t":"0","mis":"M1-1-u5-X04"}],"explanation":["30의 앞자리 3이 묶음의 수예요.","10개씩 묶음 3개는 30이에요.","묶음은 개수로 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_basic#9','math',1,1,'u5','L06','g1_1_math_u5_L06_basic','lesson_basic','M1-1-u5-C4',2,'mc','auto','50과 30 가운데 더 큰 수는 무엇인가요?',ARRAY['M1-1-u5-X16','M1-1-u5-X15']::text[],true,'{"seq":9,"concept":"M1-1-u5-C4","difficulty":2,"kind":"mc","stem":"50과 30 가운데 더 큰 수는 무엇인가요?","options":[{"t":"50","correct":true},{"t":"30","mis":"M1-1-u5-X16"},{"t":"같아요","mis":"M1-1-u5-X15"}],"explanation":["50은 묶음 5개, 30은 묶음 3개예요.","묶음이 더 많은 50이 더 커요.","몇십은 묶음 수로 견주어요."],"variant_rule":{"alt":[{"stem":"20과 40 가운데 더 작은 수는 무엇인가요?","options":[{"t":"20","correct":true},{"t":"40","mis":"M1-1-u5-X16"},{"t":"같아요","mis":"M1-1-u5-X15"}],"explanation":["20은 묶음 2개, 40은 묶음 4개예요.","묶음이 더 적은 20이 더 작아요.","몇십은 묶음 수로 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_basic#10','math',1,1,'u5','L06','g1_1_math_u5_L06_basic','lesson_basic','M1-1-u5-C4',3,'mc','auto','50은 30보다 10개씩 묶음이 몇 개 더 많은가요?',ARRAY['M1-1-u5-X05','M1-1-u5-X16']::text[],true,'{"seq":10,"concept":"M1-1-u5-C4","difficulty":3,"kind":"mc","stem":"50은 30보다 10개씩 묶음이 몇 개 더 많은가요?","options":[{"t":"2","correct":true},{"t":"20","mis":"M1-1-u5-X05"},{"t":"3","mis":"M1-1-u5-X16"}],"explanation":["50은 묶음 5개, 30은 묶음 3개예요.","5는 3보다 2 커요.","그래서 묶음이 2개 더 많아요."],"variant_rule":{"alt":[{"stem":"40은 10보다 10개씩 묶음이 몇 개 더 많은가요?","options":[{"t":"3","correct":true},{"t":"30","mis":"M1-1-u5-X05"},{"t":"4","mis":"M1-1-u5-X16"}],"explanation":["40은 묶음 4개, 10은 묶음 1개예요.","4는 1보다 3 커요.","그래서 묶음이 3개 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_challenge#1','math',1,1,'u5','L06','g1_1_math_u5_L06_challenge','lesson_challenge','M1-1-u5-C4',2,'mc','auto','그림을 보세요. 10개씩 묶음은 몇 개인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X05']::text[],true,'{"seq":1,"concept":"M1-1-u5-C4","difficulty":2,"kind":"mc","stem":"그림을 보세요. 10개씩 묶음은 몇 개인가요?","options":[{"t":"5","correct":true},{"t":"0","mis":"M1-1-u5-X04"},{"t":"50","mis":"M1-1-u5-X05"}],"explanation":["10개씩 묶음 5개와 낱개 0개예요.","묶음은 5개예요.","묶음 수와 몇십을 구별해요."],"asset":{"type":"bundle_ones","tens":5,"ones":0},"variant_rule":{"bundle":{"tens":[2,5],"ones":[0,0],"ask":"tens","cap":50}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_challenge#2','math',1,1,'u5','L06','g1_1_math_u5_L06_challenge','lesson_challenge','M1-1-u5-C4',2,'sa','auto','「삼십」을 수로 쓰면 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M1-1-u5-C4","difficulty":2,"kind":"sa","stem":"「삼십」을 수로 쓰면 무엇인가요?","answer":["30"],"explanation":["「삼십」은 10개씩 묶음 3개예요.","수로 쓰면 30이에요.","낱개가 없으면 뒤에 0을 써요."],"variant_rule":{"read2":{"range":[20,50],"ask":"num","way":"both","step10":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_challenge#3','math',1,1,'u5','L06','g1_1_math_u5_L06_challenge','lesson_challenge','M1-1-u5-C4',3,'mc','auto','아이스크림이 한 상자에 10개씩 들어 있어요. 4상자 가운데 1상자를 다 먹으면 아이스크림은 몇 개 남나요?',ARRAY['M1-1-u5-X07','M1-1-u5-X05']::text[],true,'{"seq":3,"concept":"M1-1-u5-C4","difficulty":3,"kind":"mc","stem":"아이스크림이 한 상자에 10개씩 들어 있어요. 4상자 가운데 1상자를 다 먹으면 아이스크림은 몇 개 남나요?","options":[{"t":"30","correct":true},{"t":"3","mis":"M1-1-u5-X07"},{"t":"39","mis":"M1-1-u5-X05"}],"explanation":["상자 하나는 10개짜리 묶음이에요.","4상자에서 1상자를 먹으면 3상자 — 30개예요.","상자 하나를 1개로 세지 않아요."],"variant_rule":{"alt":[{"stem":"달걀이 한 판에 10개씩 들어 있어요. 2판에 3판을 더 사면 달걀은 모두 몇 개인가요?","options":[{"t":"50","correct":true},{"t":"5","mis":"M1-1-u5-X07"},{"t":"23","mis":"M1-1-u5-X05"}],"explanation":["판 하나는 10개짜리 묶음이에요.","2판과 3판을 모으면 5판 — 50개예요.","판 수를 먼저 모으고 몇십으로 바꾸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_challenge#4','math',1,1,'u5','L06','g1_1_math_u5_L06_challenge','lesson_challenge','M1-1-u5-C4',3,'mc','auto','구명조끼 50개를 10개씩 묶으면 묶음은 몇 개가 되나요?',ARRAY['M1-1-u5-X05','M1-1-u5-X04']::text[],true,'{"seq":4,"concept":"M1-1-u5-C4","difficulty":3,"kind":"mc","stem":"구명조끼 50개를 10개씩 묶으면 묶음은 몇 개가 되나요?","options":[{"t":"5","correct":true},{"t":"50","mis":"M1-1-u5-X05"},{"t":"0","mis":"M1-1-u5-X04"}],"explanation":["10, 20, 30, 40, 50 — 10씩 세어요.","5번 세었으니 묶음 5개예요.","몇십의 앞자리가 묶음의 수예요."],"variant_rule":{"alt":[{"stem":"빨대 20개를 10개씩 묶으면 묶음은 몇 개가 되나요?","options":[{"t":"2","correct":true},{"t":"20","mis":"M1-1-u5-X05"},{"t":"0","mis":"M1-1-u5-X04"}],"explanation":["10, 20 — 10씩 세어요.","2번 세었으니 묶음 2개예요.","몇십의 앞자리가 묶음의 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_challenge#5','math',1,1,'u5','L06','g1_1_math_u5_L06_challenge','lesson_challenge','M1-1-u5-C4',3,'ox','auto','10개씩 묶음 2개와 낱개 10개는 30이에요.',ARRAY['M1-1-u5-X06']::text[],true,'{"seq":5,"concept":"M1-1-u5-C4","difficulty":3,"kind":"ox","stem":"10개씩 묶음 2개와 낱개 10개는 30이에요.","answer":"O","reason_options":[{"t":"낱개 10개는 묶음 1개라서 묶음이 3개가 되니까","correct":true},{"t":"낱개 10개는 묶지 않고 그대로 써서 210이니까","mis":"M1-1-u5-X06"}],"mis":"M1-1-u5-X06","explanation":["낱개 10개를 한 묶음으로 묶어요.","묶음 2개와 1개 — 묶음 3개, 30이에요.","낱개가 10개면 묶음 하나로 바꾸어요."],"variant_rule":{"alt":[{"stem":"10개씩 묶음 3개와 낱개 10개는 310이에요.","answer":"X","reason_options":[{"t":"낱개 10개는 묶음 1개라서 묶음 4개, 40이니까","correct":true},{"t":"묶음 3과 낱개 10을 차례로 쓰면 되니까","mis":"M1-1-u5-X06"}],"explanation":["낱개 10개를 한 묶음으로 묶어요.","묶음 3개와 1개 — 묶음 4개, 40이에요.","310은 낱개를 묶지 않고 쓴 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_challenge#6','math',1,1,'u5','L06','g1_1_math_u5_L06_challenge','lesson_challenge','M1-1-u5-C4',3,'mc','auto','스물, 서른, (        ), 쉰 — 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['M1-1-u5-X02']::text[],true,'{"seq":6,"concept":"M1-1-u5-C4","difficulty":3,"kind":"mc","stem":"스물, 서른, (        ), 쉰 — 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"마흔","correct":true},{"t":"사십","mis":"M1-1-u5-X02"},{"t":"넷십","mis":"M1-1-u5-X02"}],"explanation":["스물, 서른, 쉰은 같은 방법으로 읽은 말이에요.","서른 다음 몇십은 40 — 「마흔」이에요.","「사십」도 40이지만 앞뒤와 같은 읽기로 이어야 해요."],"variant_rule":{"alt":[{"stem":"이십, (        ), 사십, 오십 — 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"삼십","correct":true},{"t":"서른","mis":"M1-1-u5-X02"},{"t":"셋십","mis":"M1-1-u5-X02"}],"explanation":["이십, 사십, 오십은 같은 방법으로 읽은 말이에요.","이십 다음 몇십은 30 — 「삼십」이에요.","「서른」도 30이지만 앞뒤와 같은 읽기로 이어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_challenge#7','math',1,1,'u5','L06','g1_1_math_u5_L06_challenge','lesson_challenge','M1-1-u5-C4',3,'error','auto','친구들이 40에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X02','M1-1-u5-X05']::text[],true,'{"seq":7,"concept":"M1-1-u5-C4","difficulty":3,"kind":"error","stem":"친구들이 40에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하루: 40은 낱개가 4개, 묶음이 0개야.","correct":true,"mis_target":"M1-1-u5-X04"},{"t":"서아: 40은 「마흔」이라고 읽어.","mis":"M1-1-u5-X02"},{"t":"도이: 40은 10개씩 묶음 4개야.","mis":"M1-1-u5-X05"}],"explanation":["40의 앞자리 4는 묶음의 수예요.","40은 10개씩 묶음 4개, 낱개 0개예요.","하루가 자리를 거꾸로 말했어요."],"variant_rule":{"alt":[{"stem":"친구들이 30에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유나: 30은 「셋십」이라고 읽어.","correct":true,"mis_target":"M1-1-u5-X02"},{"t":"지우: 30은 「서른」이라고 읽어.","mis":"M1-1-u5-X02"},{"t":"하루: 30은 10개씩 묶음 3개야.","mis":"M1-1-u5-X05"}],"explanation":["30은 「삼십」 또는 「서른」이라고 읽어요.","「셋십」은 두 읽기를 섞은 말이에요.","유나가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_challenge#8','math',1,1,'u5','L06','g1_1_math_u5_L06_challenge','lesson_challenge','M1-1-u5-C4',4,'mc','auto','지우는 10장씩 묶은 색종이 2묶음, 하루는 3묶음을 가지고 있어요. 두 사람의 색종이를 모으면 몇 장이고, 어떻게 읽나요?',ARRAY['M1-1-u5-X05','M1-1-u5-X02']::text[],true,'{"seq":8,"concept":"M1-1-u5-C4","difficulty":4,"kind":"mc","stem":"지우는 10장씩 묶은 색종이 2묶음, 하루는 3묶음을 가지고 있어요. 두 사람의 색종이를 모으면 몇 장이고, 어떻게 읽나요?","options":[{"t":"50 — 쉰","correct":true},{"t":"5 — 다섯","mis":"M1-1-u5-X05"},{"t":"50 — 다섯십","mis":"M1-1-u5-X02"}],"explanation":["2묶음과 3묶음을 모으면 5묶음이에요.","10장씩 5묶음은 50장이에요.","50은 「쉰」 또는 「오십」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"지우는 10장씩 묶은 색종이 1묶음, 하루는 3묶음을 가지고 있어요. 두 사람의 색종이를 모으면 몇 장이고, 어떻게 읽나요?","options":[{"t":"40 — 마흔","correct":true},{"t":"4 — 넷","mis":"M1-1-u5-X05"},{"t":"40 — 넷십","mis":"M1-1-u5-X02"}],"explanation":["1묶음과 3묶음을 모으면 4묶음이에요.","10장씩 4묶음은 40장이에요.","40은 「마흔」 또는 「사십」이라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_challenge#9','math',1,1,'u5','L06','g1_1_math_u5_L06_challenge','lesson_challenge','M1-1-u5-C4',4,'mc','auto','30보다 크고 50보다 작은 몇십은 무엇인가요?',ARRAY['M1-1-u5-X13']::text[],true,'{"seq":9,"concept":"M1-1-u5-C4","difficulty":4,"kind":"mc","stem":"30보다 크고 50보다 작은 몇십은 무엇인가요?","options":[{"t":"40","correct":true},{"t":"30","mis":"M1-1-u5-X13"},{"t":"50","mis":"M1-1-u5-X13"}],"explanation":["몇십을 차례로 쓰면 10, 20, 30, 40, 50이에요.","30보다 크고 50보다 작은 것은 40이에요.","「~보다 크고 ~보다 작은」에는 양 끝 수가 들어가지 않아요."],"variant_rule":{"alt":[{"stem":"10보다 크고 40보다 작은 몇십을 모두 고른 것은 어느 것인가요?","options":[{"t":"20, 30","correct":true},{"t":"10, 20, 30, 40","mis":"M1-1-u5-X13"},{"t":"20","mis":"M1-1-u5-X13"}],"explanation":["10과 40 사이의 몇십을 찾아요.","20과 30이에요.","양 끝 수 10과 40은 들어가지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L06_challenge#10','math',1,1,'u5','L06','g1_1_math_u5_L06_challenge','lesson_challenge','M1-1-u5-C4',4,'essay','teacher','사람이 아주 많을 때 하나씩 세는 것보다 10명씩 묶어 세면 왜 좋은지, 40명을 예로 들어 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u5-C4","difficulty":4,"kind":"essay","stem":"사람이 아주 많을 때 하나씩 세는 것보다 10명씩 묶어 세면 왜 좋은지, 40명을 예로 들어 말해 보세요.","answer_guide":{"answer":"하나씩 세면 40번을 세야 하고 중간에 틀리기 쉽지만, 10명씩 묶으면 10, 20, 30, 40 — 4번만 세면 되어 빠르고 정확하다.","scoring_points":["10씩 묶어 세는 방법(10, 20, 30, 40)을 말했는가","하나씩 세기보다 빠르거나 실수가 적다는 까닭을 말했는가","40이 10개씩 묶음 4개라는 것을 말했는가"]},"explanation":["40명을 하나씩 세면 40번을 세야 해요.","10명씩 묶으면 10, 20, 30, 40 — 4번만 세요.","묶어 세면 빠르고 빠뜨리는 실수가 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L07_basic#1','math',1,1,'u5','L07','g1_1_math_u5_L07_basic','lesson_basic','M1-1-u5-C5',1,'mc','auto','10개씩 묶음 2개와 낱개 5개는 얼마인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X05']::text[],true,'{"seq":1,"concept":"M1-1-u5-C5","difficulty":1,"kind":"mc","stem":"10개씩 묶음 2개와 낱개 5개는 얼마인가요?","options":[{"t":"25","correct":true},{"t":"52","mis":"M1-1-u5-X04"},{"t":"7","mis":"M1-1-u5-X05"}],"explanation":["묶음 2개는 20이에요.","거기에 낱개 5개를 더하면 25예요.","묶음 수를 앞에, 낱개 수를 뒤에 써요."],"asset":{"type":"bundle_ones","tens":2,"ones":5},"variant_rule":{"bundle":{"tens":[2,4],"ones":[1,9],"ask":"number","cap":50}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L07_basic#2','math',1,1,'u5','L07','g1_1_math_u5_L07_basic','lesson_basic','M1-1-u5-C5',1,'sa','auto','그림을 보세요. 낱개는 몇 개인가요?','{}'::text[],true,'{"seq":2,"concept":"M1-1-u5-C5","difficulty":1,"kind":"sa","stem":"그림을 보세요. 낱개는 몇 개인가요?","answer":["4"],"explanation":["10개씩 묶음 3개와 낱개 4개예요.","낱개는 4개예요.","묶음과 낱개를 나누어 세어요."],"asset":{"type":"bundle_ones","tens":3,"ones":4},"variant_rule":{"bundle":{"tens":[2,4],"ones":[1,9],"ask":"ones","cap":50}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L07_basic#3','math',1,1,'u5','L07','g1_1_math_u5_L07_basic','lesson_basic','M1-1-u5-C5',1,'mc','auto','23을 바르게 읽은 것은 어느 것인가요?',ARRAY['M1-1-u5-X02','M1-1-u5-X04']::text[],true,'{"seq":3,"concept":"M1-1-u5-C5","difficulty":1,"kind":"mc","stem":"23을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"이십삼","correct":true},{"t":"스물삼","mis":"M1-1-u5-X02"},{"t":"삼십이","mis":"M1-1-u5-X04"}],"explanation":["23은 10개씩 묶음 2개와 낱개 3개예요.","「이십삼」 또는 「스물셋」이라고 읽어요.","한 수를 읽을 때 두 가지 읽기를 섞지 않아요."],"variant_rule":{"read2":{"range":[21,49],"ask":"read","way":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L07_basic#4','math',1,1,'u5','L07','g1_1_math_u5_L07_basic','lesson_basic','M1-1-u5-C5',1,'mc','auto','그림을 보세요. 10개씩 묶음은 몇 개인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X05']::text[],true,'{"seq":4,"concept":"M1-1-u5-C5","difficulty":1,"kind":"mc","stem":"그림을 보세요. 10개씩 묶음은 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"1","mis":"M1-1-u5-X04"},{"t":"41","mis":"M1-1-u5-X05"}],"explanation":["10개씩 묶음 4개와 낱개 1개예요.","묶음은 4개예요.","묶음 수가 앞자리 숫자가 돼요."],"asset":{"type":"bundle_ones","tens":4,"ones":1},"variant_rule":{"bundle":{"tens":[2,4],"ones":[1,9],"ask":"tens","cap":50}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L07_basic#5','math',1,1,'u5','L07','g1_1_math_u5_L07_basic','lesson_basic','M1-1-u5-C5',2,'mc','auto','「서른넷」을 수로 쓰면 무엇인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X07']::text[],true,'{"seq":5,"concept":"M1-1-u5-C5","difficulty":2,"kind":"mc","stem":"「서른넷」을 수로 쓰면 무엇인가요?","options":[{"t":"34","correct":true},{"t":"43","mis":"M1-1-u5-X04"},{"t":"304","mis":"M1-1-u5-X07"}],"explanation":["「서른넷」은 10개씩 묶음 3개와 낱개 4개예요.","수로 쓰면 34예요.","「서른」을 30으로 쓰고 4를 이어 쓰면 304가 되어 틀려요."],"variant_rule":{"read2":{"range":[21,49],"ask":"num","way":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L07_basic#6','math',1,1,'u5','L07','g1_1_math_u5_L07_basic','lesson_basic','M1-1-u5-C5',2,'ox','auto','10개씩 묶음 4개와 낱개 7개는 47이에요.',ARRAY['M1-1-u5-X05']::text[],true,'{"seq":6,"concept":"M1-1-u5-C5","difficulty":2,"kind":"ox","stem":"10개씩 묶음 4개와 낱개 7개는 47이에요.","answer":"O","reason_options":[{"t":"묶음 수 4를 앞에, 낱개 수 7을 뒤에 쓰니까","correct":true},{"t":"4와 7을 모으면 11이니까","mis":"M1-1-u5-X05"}],"mis":"M1-1-u5-X05","explanation":["묶음 4개는 40이에요.","40과 낱개 7개를 더하면 47이에요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"34는 10개씩 묶음 4개와 낱개 3개예요.","answer":"X","reason_options":[{"t":"앞의 3이 묶음, 뒤의 4가 낱개니까","correct":true},{"t":"뒤의 숫자가 묶음의 수니까","mis":"M1-1-u5-X04"}],"explanation":["34의 앞자리 3이 묶음의 수예요.","34는 묶음 3개와 낱개 4개예요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L07_basic#7','math',1,1,'u5','L07','g1_1_math_u5_L07_basic','lesson_basic','M1-1-u5-C5',2,'match','auto','수와 읽는 말을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u5-C5","difficulty":2,"kind":"match","stem":"수와 읽는 말을 알맞게 이어 보세요.","pairs":[{"l":"27","r":"스물일곱"},{"l":"38","r":"삼십팔"},{"l":"45","r":"마흔다섯"}],"mis":"M1-1-u5-X02","explanation":["27은 스물일곱 또는 이십칠이에요.","38은 삼십팔 또는 서른여덟, 45는 마흔다섯 또는 사십오예요.","한 수를 읽을 때 두 가지 읽기를 섞지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 수와 읽는 말을 알맞게 이어 보세요.","pairs":[{"l":"31","r":"서른하나"},{"l":"42","r":"사십이"},{"l":"29","r":"스물아홉"}],"explanation":["31은 서른하나 또는 삼십일이에요.","42는 사십이 또는 마흔둘, 29는 스물아홉 또는 이십구예요.","한 수를 읽을 때 두 가지 읽기를 섞지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L07_basic#8','math',1,1,'u5','L07','g1_1_math_u5_L07_basic','lesson_basic','M1-1-u5-C5',2,'blank','auto','36은 10개씩 묶음 (        )개와 낱개 6개예요.',ARRAY['M1-1-u5-X04','M1-1-u5-X05']::text[],true,'{"seq":8,"concept":"M1-1-u5-C5","difficulty":2,"kind":"blank","stem":"36은 10개씩 묶음 (        )개와 낱개 6개예요.","options":[{"t":"3","correct":true},{"t":"6","mis":"M1-1-u5-X04"},{"t":"30","mis":"M1-1-u5-X05"}],"explanation":["36의 앞자리 3이 묶음의 수예요.","36은 묶음 3개와 낱개 6개예요.","묶음은 몇 개인지 개수로 세어요."],"variant_rule":{"alt":[{"stem":"10개씩 묶음 4개와 낱개 (        )개는 42예요.","options":[{"t":"2","correct":true},{"t":"4","mis":"M1-1-u5-X04"},{"t":"42","mis":"M1-1-u5-X06"}],"explanation":["42의 뒷자리 2가 낱개의 수예요.","묶음 4개와 낱개 2개면 42예요.","낱개는 뒷자리에 써요."]},{"stem":"10개씩 묶음 (        )개와 낱개 8개는 28이에요.","options":[{"t":"2","correct":true},{"t":"8","mis":"M1-1-u5-X04"},{"t":"20","mis":"M1-1-u5-X05"}],"explanation":["28의 앞자리 2가 묶음의 수예요.","묶음 2개와 낱개 8개면 28이에요.","묶음은 개수로 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L07_basic#9','math',1,1,'u5','L07','g1_1_math_u5_L07_basic','lesson_basic','M1-1-u5-C5',2,'mc','auto','50은 10개씩 묶음 몇 개와 낱개 몇 개인가요?',ARRAY['M1-1-u5-X04','M1-1-u5-X06']::text[],true,'{"seq":9,"concept":"M1-1-u5-C5","difficulty":2,"kind":"mc","stem":"50은 10개씩 묶음 몇 개와 낱개 몇 개인가요?","options":[{"t":"묶음 5개, 낱개 0개","correct":true},{"t":"묶음 0개, 낱개 5개","mis":"M1-1-u5-X04"},{"t":"묶음 4개, 낱개 10개","mis":"M1-1-u5-X06"}],"explanation":["50의 앞자리 5는 묶음, 뒷자리 0은 낱개예요.","50은 묶음 5개, 낱개 0개예요.","낱개가 10개면 묶음 하나로 바꾸어 써요."],"variant_rule":{"alt":[{"stem":"40은 10개씩 묶음 몇 개와 낱개 몇 개인가요?","options":[{"t":"묶음 4개, 낱개 0개","correct":true},{"t":"묶음 0개, 낱개 4개","mis":"M1-1-u5-X04"},{"t":"묶음 3개, 낱개 10개","mis":"M1-1-u5-X06"}],"explanation":["40의 앞자리 4는 묶음, 뒷자리 0은 낱개예요.","40은 묶음 4개, 낱개 0개예요.","낱개가 10개면 묶음 하나로 바꾸어 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L07_basic#10','math',1,1,'u5','L07','g1_1_math_u5_L07_basic','lesson_basic','M1-1-u5-C5',3,'mc','auto','사탕이 10개씩 묶음 2개와 낱개 13개 있어요. 사탕은 모두 몇 개인가요?',ARRAY['M1-1-u5-X06','M1-1-u5-X05']::text[],true,'{"seq":10,"concept":"M1-1-u5-C5","difficulty":3,"kind":"mc","stem":"사탕이 10개씩 묶음 2개와 낱개 13개 있어요. 사탕은 모두 몇 개인가요?","options":[{"t":"33","correct":true},{"t":"213","mis":"M1-1-u5-X06"},{"t":"15","mis":"M1-1-u5-X05"}],"explanation":["낱개 13개 가운데 10개를 묶으면 묶음 1개와 낱개 3개예요.","묶음은 2개와 1개 — 3개, 낱개는 3개예요.","그래서 사탕은 33개예요."],"variant_rule":{"alt":[{"stem":"사탕이 10개씩 묶음 3개와 낱개 12개 있어요. 사탕은 모두 몇 개인가요?","options":[{"t":"42","correct":true},{"t":"312","mis":"M1-1-u5-X06"},{"t":"15","mis":"M1-1-u5-X05"}],"explanation":["낱개 12개 가운데 10개를 묶으면 묶음 1개와 낱개 2개예요.","묶음은 3개와 1개 — 4개, 낱개는 2개예요.","그래서 사탕은 42개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
