INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_review_a#11','math',1,1,'u5','','g1_1_math_u5_review_a','unit_review','M1-1-u5-C4',2,'mc','auto','「마흔」을 수로 쓰면 무엇인가요?',ARRAY['M1-1-u5-X05','M1-1-u5-X07']::text[],true,'{"seq":11,"concept":"M1-1-u5-C4","difficulty":2,"kind":"mc","stem":"「마흔」을 수로 쓰면 무엇인가요?","options":[{"t":"40","correct":true},{"t":"50","mis":"M1-1-u5-X05"},{"t":"4","mis":"M1-1-u5-X07"}],"explanation":["「마흔」은 10개씩 묶음 4개예요.","수로 쓰면 40이에요.","낱개가 없으면 뒤에 0을 써요."],"variant_rule":{"read2":{"range":[20,50],"ask":"num","way":"both","step10":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
