INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_review_a#13','math',1,1,'u5','','g1_1_math_u5_review_a','unit_review','M1-1-u5-C6',2,'mc','auto','25와 27 사이에 있는 수는 무엇인가요?',ARRAY['M1-1-u5-X13']::text[],true,'{"seq":13,"concept":"M1-1-u5-C6","difficulty":2,"kind":"mc","stem":"25와 27 사이에 있는 수는 무엇인가요?","options":[{"t":"26","correct":true},{"t":"27","mis":"M1-1-u5-X13"},{"t":"25","mis":"M1-1-u5-X13"}],"explanation":["25 바로 뒤의 수를 찾아요.","25, 26, 27 — 사이에 있는 수는 26이에요.","사이의 수에는 양쪽 끝 수가 들어가지 않아요."],"variant_rule":{"seq50":{"ask":"between","range":[11,49]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_review_a#14','math',1,1,'u5','','g1_1_math_u5_review_a','unit_review','M1-1-u5-C7',2,'mc','auto','38과 33 중에서 더 작은 수는 무엇인가요?',ARRAY['M1-1-u5-X15','M1-1-u5-X14']::text[],true,'{"seq":14,"concept":"M1-1-u5-C7","difficulty":2,"kind":"mc","stem":"38과 33 중에서 더 작은 수는 무엇인가요?","options":[{"t":"33","correct":true},{"t":"38","mis":"M1-1-u5-X15"},{"t":"43","mis":"M1-1-u5-X14"}],"explanation":["묶음이 같으니 낱개를 봐요 — 8과 3이에요.","그래서 더 작은 수는 33이에요.","묶음이 같을 때만 낱개를 견주어요."],"variant_rule":{"cmp2":{"range":[10,50],"cap":50,"ask":"small","same_tens":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
